// ============================================================
// STATS DATE AND PERIOD NAVIGATION HELPERS
// ============================================================
function getStatsDateRange() {
  let start, end;
  if (state.statsPeriodType === 'weekly') {
    start = new Date(state.statsDate);
    const day = start.getDay();
    const weekStartDay = parseInt(localStorage.getItem('app_week_start') || '1', 10);
    let diff = day - weekStartDay;
    if (diff < 0) {
      diff += 7;
    }
    start.setDate(start.getDate() - diff);
    start.setHours(0, 0, 0, 0);

    end = new Date(start);
    end.setDate(start.getDate() + 6);
    end.setHours(23, 59, 59, 999);
  } else if (state.statsPeriodType === 'monthly') {
    const monthStartDay = parseInt(localStorage.getItem('app_month_start') || '1', 10);
    if (monthStartDay === 1) {
      start = new Date(state.statsDate.getFullYear(), state.statsDate.getMonth(), 1, 0, 0, 0, 0);
      end = new Date(state.statsDate.getFullYear(), state.statsDate.getMonth() + 1, 0, 23, 59, 59, 999);
    } else {
      start = new Date(state.statsDate.getFullYear(), state.statsDate.getMonth(), monthStartDay, 0, 0, 0, 0);
      end = new Date(state.statsDate.getFullYear(), state.statsDate.getMonth() + 1, monthStartDay - 1, 23, 59, 59, 999);
    }
  } else if (state.statsPeriodType === 'annually') {
    start = new Date(state.statsDate.getFullYear(), 0, 1, 0, 0, 0, 0);
    end = new Date(state.statsDate.getFullYear(), 11, 31, 23, 59, 59, 999);
  } else if (state.statsPeriodType === 'period') {
    start = new Date(state.statsCustomStart + 'T00:00:00');
    end = new Date(state.statsCustomEnd + 'T23:59:59');
  }
  return { start, end };
}

function syncStatsDate() {
  state.statsDate.setDate(15);
  state.statsDate.setFullYear(state.selectedYear);
  state.statsDate.setMonth(state.selectedMonth);
}

function formatStatsPeriodTitle(start, end) {
  if (state.statsPeriodType === 'monthly') {
    return `${getMonthName(start.getMonth(), true)} ${start.getFullYear()}`;
  }
  if (state.statsPeriodType === 'annually') {
    return `${start.getFullYear()}`;
  }

  // Weekly or Custom Period
  const startDay = start.getDate();
  const startMonthShort = getMonthName(start.getMonth(), true);
  const startYear = start.getFullYear();

  const endDay = end.getDate();
  const endMonthShort = getMonthName(end.getMonth(), true);
  const endYear = end.getFullYear();

  if (startYear !== endYear) {
    return `${startDay} ${startMonthShort} ${startYear} - ${endDay} ${endMonthShort} ${endYear}`;
  } else if (start.getMonth() !== end.getMonth()) {
    return `${startDay} ${startMonthShort} - ${endDay} ${endMonthShort} ${startYear}`;
  } else {
    return `${startDay} - ${endDay} ${startMonthShort} ${startYear}`;
  }
}

function wrapPeriodTitleWithSpans(titleText) {
  if (!titleText) return '';
  const match = titleText.trim().match(/^(.*?)(?:\s+)?(\d{4})$/);
  if (match && match[1]) {
    const mainPart = match[1].trim();
    const yearPart = match[2];
    return `<span class="month-part">${mainPart}</span><span class="year-part" style="color: var(--text-secondary); margin-left: 6px;">${yearPart}</span>`;
  }
  if (/^\d{4}$/.test(titleText.trim())) {
    return `<span class="year-part">${titleText.trim()}</span>`;
  }
  return `<span class="month-part">${titleText}</span>`;
}

// ============================================================
// EMOJI STRIPPING - handles surrogate pairs correctly
// Excel exports emoji as surrogate pairs (2 UTF-16 code units)
// We need to skip past them to get the Greek text
// ============================================================
function stripLeadingEmoji(str) {
  if (!str) return '';
  let i = 0;
  const codes = [];
  for (let j = 0; j < str.length; j++) {
    codes.push(str.charCodeAt(j));
  }
  while (i < codes.length) {
    const c = codes[i];
    // High surrogate (emoji start)
    if (c >= 0xD800 && c <= 0xDBFF) {
      i += 2; // skip surrogate pair (2 code units)
      // Skip trailing space after emoji
      while (i < codes.length && codes[i] === 0x20) i++;
    }
    // BMP private use area
    else if (c >= 0xE000 && c <= 0xF8FF) {
      i += 1;
      while (i < codes.length && codes[i] === 0x20) i++;
    }
    // BMP symbols / dingbats (like U+2764 heart, etc.)
    else if (c >= 0x2600 && c <= 0x27BF) {
      i += 1;
      while (i < codes.length && codes[i] === 0x20) i++;
    }
    // Variation selector or replacement char
    else if (c === 0xFFFD || (c >= 0xFE00 && c <= 0xFE0F)) {
      i += 1;
      while (i < codes.length && codes[i] === 0x20) i++;
    }
    // Regular character - stop stripping
    else {
      break;
    }
  }
  return str.substring(i).trim();
}

// Get emoji codepoint from first surrogate pair (for category lookup)
function getFirstEmojiCodepoint(str) {
  if (!str || str.length < 2) return null;
  const high = str.charCodeAt(0);
  const low = str.charCodeAt(1);
  if (high >= 0xD800 && high <= 0xDBFF && low >= 0xDC00 && low <= 0xDFFF) {
    const cp = 0x10000 + ((high - 0xD800) * 0x400) + (low - 0xDC00);
    return cp.toString(16).toUpperCase().padStart(5, '0');
  }
  return null;
}

// Resolve category from raw Excel string.
// Strategy: Keep emoji-prefixed names intact to align with user's Excel files.
function resolveCategoryInfo(rawCategory, transType) {
  if (!rawCategory) return null;

  const trimmed = rawCategory.trim();
  const upperName = trimmed.toUpperCase();

  // 1. Find exact match in state.categories
  let cat = state.categories.find(c =>
    c.name && c.name.toUpperCase() === upperName
  );
  if (cat) return cat;

  // 2. Find match in CATEGORY_EMOJI_MAP by codepoint
  const cp = getFirstEmojiCodepoint(trimmed);
  const emojiInfo = cp ? CATEGORY_EMOJI_MAP[cp] : null;
  if (emojiInfo) {
    let mappedCat = state.categories.find(c =>
      c.name && c.name.toUpperCase() === emojiInfo.name.toUpperCase()
    );
    if (mappedCat) return mappedCat;
    return emojiInfo;
  }

  // 3. Not found - return info to create new category
  return {
    name: trimmed,
    type: transType,
    icon: transType === 'income' ? '💰' : '💸',
    color: getRandomColor(),
  };
}

// ============================================================
// NOTIFICATION CENTER & LOCAL NOTIFICATIONS
// ============================================================
function uuidToNotificationId(uuid) {
  if (!uuid) return 1;
  let hash = 0;
  for (let i = 0; i < uuid.length; i++) {
    hash = uuid.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash & 0x7FFFFFFF);
}

function loadNotifications() {
  try {
    const stored = localStorage.getItem('state_notifications') || localStorage.getItem('money_manager_notifications');
    state.notifications = stored ? JSON.parse(stored) : [];
  } catch (err) {
    console.warn('Failed to load notifications from localStorage', err);
    state.notifications = [];
  }
  updateNotificationBadge();
}

function saveNotifications() {
  try {
    localStorage.setItem('state_notifications', JSON.stringify(state.notifications || []));
  } catch (err) {
    console.warn('Failed to save notifications to localStorage', err);
  }
}

function updateNotificationBadge() {
  const badge = document.getElementById('header-notification-badge');
  if (badge) {
    const hasUnread = state.notifications && state.notifications.some(n => !n.read);
    badge.style.display = hasUnread ? 'block' : 'none';
  }
}

function addInAppNotification(title, body, action = null) {
  state.notifications = state.notifications || [];
  const notif = {
    id: generateUUID(),
    title: title,
    body: body,
    action: action,
    read: false,
    timestamp: new Date().toISOString()
  };
  state.notifications.unshift(notif);
  if (state.notifications.length > 250) {
    state.notifications = state.notifications.slice(0, 250);
  }
  saveNotifications();
  updateNotificationBadge();
  if (document.getElementById('notification-modal') && document.getElementById('notification-modal').classList.contains('active')) {
    renderNotificationList();
  }
}

function openNotificationCenterModal() {
  if (state.notifications) {
    state.notifications.forEach(n => n.read = true);
  }
  saveNotifications();
  updateNotificationBadge();
  renderNotificationList();
  openModal('notification-modal');
}

function renderNotificationList() {
  const listEl = document.getElementById('notification-list');
  if (!listEl) return;
  listEl.innerHTML = '';
  if (!state.notifications || state.notifications.length === 0) {
    listEl.innerHTML = `
      <div class="empty-notifications">
        <div style="font-size: 40px; margin-bottom: 12px; filter: grayscale(1);">🔔</div>
        <div>${state.lang === 'el' ? 'Δεν υπάρχουν ειδοποιήσεις.' : 'No notifications.'}</div>
      </div>
    `;
    return;
  }
  state.notifications.forEach(notif => {
    const card = document.createElement('div');
    card.className = `notification-card${notif.read ? ' read' : ''}`;
    if (notif.action) {
      card.classList.add('clickable');
    }
    const formattedTime = new Date(notif.timestamp).toLocaleString(state.lang === 'el' ? 'el-GR' : 'en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
    card.innerHTML = `
      <div class="notification-header">
        <span class="notification-title">${escapeHtml(notif.title)}</span>
        <span class="notification-time">${formattedTime}</span>
      </div>
      <div class="notification-body">${escapeHtml(notif.body)}</div>
    `;
    if (notif.action) {
      card.addEventListener('click', () => {
        handleNotificationAction(notif.action);
        closeModal('notification-modal');
      });
    }
    listEl.appendChild(card);
  });
}

function clearNotifications() {
  state.notifications = [];
  saveNotifications();
  updateNotificationBadge();
  renderNotificationList();
}

function handleNotificationAction(action) {
  if (!action) return;
  if (action.type === 'open_note' && action.noteId) {
    openNoteEditor(action.noteId);
  } else if (action.type === 'open_transactions') {
    const transTabBtn = document.querySelector('[data-tab="transactions"]');
    if (transTabBtn) transTabBtn.click();
  } else if (action.type === 'open_analytics') {
    const analyticsTabBtn = document.querySelector('[data-tab="analytics"]');
    if (analyticsTabBtn) analyticsTabBtn.click();
  }
}

function handleIncomingLocalNotification(notification) {
  if (!notification) return;
  const title = notification.title || (state.lang === 'el' ? 'Ειδοποίηση' : 'Notification');
  const body = notification.body || '';
  const extra = notification.extra || null;
  let action = null;
  if (extra) {
    if (extra.type === 'note_reminder' && extra.noteId) {
      action = { type: 'open_note', noteId: extra.noteId };
    } else if (extra.type === 'daily_reminder') {
      action = { type: 'open_transactions' };
    } else if (extra.type === 'recurring_alert') {
      action = { type: 'open_transactions' };
    } else if (extra.type === 'high_expense') {
      action = { type: 'open_transactions' };
    }
  }
  addInAppNotification(title, body, action);
}

async function scheduleDailyReminder(enabled, timeString) {
  const isNative = typeof window.Capacitor !== 'undefined' && typeof window.Capacitor.isNativePlatform === 'function' && window.Capacitor.isNativePlatform();
  if (!isNative) {
    return;
  }

  // 1. Primary: Pure Native ReliableNotification Plugin (Bypasses WebView, auto-reschedules on boot/alarm)
  const ReliableNotification = window.Capacitor.Plugins && window.Capacitor.Plugins.ReliableNotification;
  if (ReliableNotification) {
    try {
      // Check / request POST_NOTIFICATIONS permission
      if (window.Capacitor.Plugins.LocalNotifications) {
        try {
          if (typeof window.stabilizeLayoutBeforeNativePicker === 'function') {
            window.stabilizeLayoutBeforeNativePicker();
          }
          await window.Capacitor.Plugins.LocalNotifications.requestPermissions();
        } catch (pErr) { }
      }

      if (!enabled) {
        await ReliableNotification.cancelDailyReminder();
        return;
      }

      const [hours, minutes] = (timeString || '21:00').split(':').map(Number);
      const title = state.lang === 'el' ? 'Καταγραφή Εξόδων' : 'Log Expenses';
      const body = state.lang === 'el' ? 'Έχεις καταγράψει τα σημερινά έξοδά σου;' : 'Have you logged today\'s expenses?';

      await ReliableNotification.scheduleDailyReminder({
        hour: hours,
        minute: minutes,
        title: title,
        body: body,
        enabled: true
      });
      console.log('ReliableNotification armed successfully for', hours, minutes);
      return;
    } catch (err) {
      console.warn('ReliableNotification failed, falling back to LocalNotifications:', err);
    }
  }

  // 2. Secondary Fallback: Capacitor LocalNotifications
  const LocalNotifications = window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications;
  if (LocalNotifications) {
    try {
      await LocalNotifications.cancel({ notifications: [{ id: 9999 }] });
      if (!enabled) return;
      const perm = await LocalNotifications.requestPermissions();
      if (perm.display !== 'granted') {
        console.warn('Notification permission denied');
        return;
      }

      try {
        if (typeof LocalNotifications.createChannel === 'function') {
          await LocalNotifications.createChannel({
            id: 'budget_reminders',
            name: 'Budget Assistant Reminders',
            description: 'Daily expense reminders and alerts',
            importance: 5,
            visibility: 1,
            vibration: true,
            lights: true,
            lightColor: '#7c6af7'
          });
        }
      } catch (chanErr) { }

      const [hours, minutes] = (timeString || '21:00').split(':').map(Number);

      await LocalNotifications.schedule({
        notifications: [
          {
            id: 9999,
            title: state.lang === 'el' ? 'Καταγραφή Εξόδων' : 'Log Expenses',
            body: state.lang === 'el' ? 'Έχεις καταγράψει τα σημερινά έξοδά σου;' : 'Have you logged today\'s expenses?',
            channelId: 'budget_reminders',
            smallIcon: 'ic_launcher_round',
            iconColor: '#0F1219',
            schedule: {
              on: {
                hour: hours,
                minute: minutes
              },
              allowWhileIdle: true
            },
            sound: null,
            attachments: null,
            actionTypeId: '',
            extra: {
              type: 'daily_reminder'
            }
          }
        ]
      });
    } catch (err) {
      console.error('Error scheduling daily reminder fallback:', err);
    }
  }
}

