function openSubscriptionsHubModal() {
  renderSubscriptionsHub();
  openModal('subscriptions-hub-modal');
}
window.openSubscriptionsHubModal = openSubscriptionsHubModal;

function renderSubscriptionsHub() {
  if (typeof SubscriptionEngine === 'undefined') return;

  const lang = state.lang || 'el';
  const currSym = getCurrencySymbol();

  const analysis = SubscriptionEngine.analyzeMonthlySubscriptions({
    templates: state.recurringTemplates || [],
    transactions: state.transactions || [],
    referenceDate: new Date()
  });

  state._lastSubscriptionsAnalysis = analysis;

  // 1. Metric values
  const totalValEl = document.getElementById('sub-hub-total-val');
  const paidValEl = document.getElementById('sub-hub-paid-val');
  const pendingValEl = document.getElementById('sub-hub-pending-val');

  if (totalValEl) totalValEl.textContent = `${currSym} ${formatDisplayAmount(analysis.totalMonthly)}`;
  if (paidValEl) paidValEl.textContent = `${currSym} ${formatDisplayAmount(analysis.totalPaid)}`;
  if (pendingValEl) pendingValEl.textContent = `${currSym} ${formatDisplayAmount(analysis.totalPending)}`;

  // 2. Smart Detection section
  const detectContainer = document.getElementById('sub-hub-detection-container');
  if (detectContainer) {
    const suggestions = SubscriptionEngine.detectRecurringPatterns({
      transactions: state.transactions || [],
      existingTemplates: state.recurringTemplates || [],
      referenceDate: new Date()
    });

    if (suggestions.length > 0) {
      let detectHtml = `
        <div class="sub-detection-box">
          <div class="sub-detection-title">
            <i class="fa-solid fa-wand-magic-sparkles"></i>
            <span>${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_smart_detection_title']) || 'Έξυπνη Ανίχνευση Συνδρομών'}</span>
          </div>
          <div class="sub-detection-desc">
            ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_smart_detection_desc']) || 'Εντοπίστηκαν επαναλαμβανόμενα έξοδα στο ιστορικό σας:'}
          </div>
          <div style="display: flex; flex-direction: column; gap: 6px;">
      `;

      suggestions.slice(0, 3).forEach((sug, idx) => {
        detectHtml += `
          <div class="sub-detection-item">
            <div style="display: flex; align-items: center; gap: 8px; min-width: 0;">
              <span style="font-size: 14px;">⚡</span>
              <div style="display: flex; flex-direction: column; min-width: 0;">
                <span style="font-size: 13px; font-weight: 700; color: #ffffff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${escapeHtml(sug.note)}</span>
                <span style="font-size: 11px; color: var(--text-secondary);">${currSym} ${formatDisplayAmount(sug.amount)} • Ημέρα ~${sug.suggestedDay}</span>
              </div>
            </div>
            <button type="button" onclick="acceptDetectedSubscription(${idx})"
              style="padding: 5px 10px; border-radius: 8px; background: var(--accent); color: white; border: none; font-size: 11px; font-weight: 700; cursor: pointer; white-space: nowrap;">
              ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_btn_add_suggested']) || '+ Προσθήκη'}
            </button>
          </div>
        `;
      });

      detectHtml += `</div></div>`;
      detectContainer.innerHTML = detectHtml;
      detectContainer.style.display = 'block';
      window._activeSubscriptionSuggestions = suggestions;
    } else {
      detectContainer.style.display = 'none';
      detectContainer.innerHTML = '';
      window._activeSubscriptionSuggestions = [];
    }
  }

  // 3. Items list
  const listContainer = document.getElementById('sub-hub-items-list');
  if (listContainer) {
    if (analysis.items.length === 0) {
      listContainer.innerHTML = `
        <div style="text-align: center; padding: 32px 16px; color: var(--text-secondary); font-size: 13.5px;">
          <div style="font-size: 32px; margin-bottom: 8px; opacity: 0.6;">📅</div>
          <div>${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_no_subs']) || 'Δεν υπάρχουν καταχωρημένες πάγιες υποχρεώσεις.'}</div>
          <button type="button" onclick="closeModal('subscriptions-hub-modal'); openModal('recurring-picker-modal');"
            style="margin-top: 12px; padding: 8px 16px; border-radius: 12px; background: rgba(var(--accent-rgb), 0.15); border: 1px solid var(--accent); color: var(--primary); font-size: 12.5px; font-weight: 700; cursor: pointer;">
            ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_btn_add_suggested']) || '+ Προσθήκη Πάγιας Εντολής'}
          </button>
        </div>
      `;
    } else {
      let listHtml = '';
      analysis.items.forEach(item => {
        const catInfo = (typeof getCategoryInfo === 'function') ? getCategoryInfo(item.category, 'expense') : { icon: '💳', color: '#6366f1' };
        const iconHtml = (typeof renderCategoryIconHtml === 'function')
          ? renderCategoryIconHtml(item.category, { size: 'md', customColor: catInfo.color, transType: 'expense' })
          : `<div style="width: 38px; height: 38px; border-radius: 10px; background: ${catInfo.color}20; color: ${catInfo.color}; display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0;">${catInfo.icon || '💳'}</div>`;

        let statusBadge = '';
        let dueTimingText = '';

        if (item.isPaid) {
          statusBadge = `<span class="sub-status-badge paid"><i class="fa-solid fa-check"></i> ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_status_paid']) || 'Πληρώθηκε'}</span>`;
          if (item.matchedTransaction && item.matchedTransaction.date) {
            dueTimingText = `${formatShortDate(item.matchedTransaction.date)}`;
          } else {
            dueTimingText = `${item.dueDay} ${lang === 'el' ? 'μηνός' : 'of month'}`;
          }
        } else if (item.isOverdue) {
          statusBadge = `<span class="sub-status-badge overdue"><i class="fa-solid fa-triangle-exclamation"></i> ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_status_overdue']) || 'Καθυστέρηση'}</span>`;
          dueTimingText = `${item.dueDay} ${lang === 'el' ? 'μηνός' : 'of month'}`;
        } else {
          statusBadge = `<span class="sub-status-badge pending"><i class="fa-regular fa-clock"></i> ${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_status_pending']) || 'Εκκρεμεί'}</span>`;
          if (item.daysUntilDue === 0) {
            dueTimingText = lang === 'el' ? 'Σήμερα' : 'Today';
          } else if (item.daysUntilDue === 1) {
            dueTimingText = lang === 'el' ? 'Αύριο' : 'Tomorrow';
          } else {
            dueTimingText = lang === 'el' ? `σε ${item.daysUntilDue} ημ.` : `in ${item.daysUntilDue}d`;
          }
        }

        listHtml += `
          <div class="sub-item-card">
            <div style="display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1;">
              ${iconHtml}
              <div style="display: flex; flex-direction: column; min-width: 0;">
                <div style="font-family: 'Outfit', sans-serif; font-size: 14px; font-weight: 700; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
                  ${escapeHtml(item.title)}
                </div>
                <div style="font-size: 11.5px; color: var(--text-secondary); display: flex; align-items: center; gap: 6px; margin-top: 2px;">
                  <span>${dueTimingText}</span>
                  <span>•</span>
                  <span>${getCategoryDisplayName ? getCategoryDisplayName(item.category) : item.category}</span>
                </div>
              </div>
            </div>

            <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex-shrink: 0;">
              <div style="font-family: 'Outfit', sans-serif; font-size: 14px; font-weight: 800; color: ${item.isPaid ? 'var(--text-secondary)' : '#ffffff'};">
                ${currSym} ${formatDisplayAmount(item.amount)}
              </div>
              <div style="display: flex; align-items: center; gap: 6px;">
                ${statusBadge}
                ${!item.isPaid ? `
                  <button type="button" class="sub-quick-pay-btn" onclick="quickPaySubscription('${item.id}')">
                    <i class="fa-solid fa-bolt"></i> <span>${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['sub_hub_btn_pay']) || 'Πληρωμή'}</span>
                  </button>
                ` : ''}
              </div>
            </div>
          </div>
        `;
      });
      listContainer.innerHTML = listHtml;
    }
  }
}
window.renderSubscriptionsHub = renderSubscriptionsHub;

function acceptDetectedSubscription(suggestionIndex) {
  const suggestions = window._activeSubscriptionSuggestions || [];
  const sug = suggestions[suggestionIndex];
  if (!sug) return;

  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const dueDay = Math.min(sug.suggestedDay || 1, new Date(year, month + 1, 0).getDate());
  const startDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(dueDay).padStart(2, '0')}`;

  const newTemplate = {
    id: generateUUID(),
    category: sug.category || 'Bills',
    note: sug.note,
    amount: sug.amount,
    currency: sug.currency || state.mainCurrency || 'EUR',
    type: 'expense',
    preset: 'monthly',
    days: [dueDay],
    startDate: startDateStr,
    endType: 'perpetual',
    is_shared: false
  };

  if (!state.recurringTemplates) state.recurringTemplates = [];
  state.recurringTemplates.push(newTemplate);
  localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));

  if (state.supabaseClient && state.currentUser) {
    if (typeof mapTemplateToDb === 'function') {
      state.supabaseClient.from('recurring_templates').upsert([mapTemplateToDb(newTemplate)])
        .catch(err => console.warn('Failed to sync accepted subscription template:', err));
    }
  }

  if (typeof showToast === 'function') {
    showToast(state.lang === 'el' ? '✓ Η συνδρομή προστέθηκε στα πάγια!' : '✓ Subscription added to recurring bills!', 'success');
  }
  renderSubscriptionsHub();
  updateSafeToSpendUI();
}
window.acceptDetectedSubscription = acceptDetectedSubscription;

function quickPaySubscription(templateId) {
  const tpl = (state.recurringTemplates || []).find(t => String(t.id) === String(templateId));
  if (!tpl) return;

  const todayStr = (typeof formatISODateLocal === 'function') ? formatISODateLocal(new Date()) : new Date().toISOString().slice(0, 10);
  const now = new Date();
  const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

  const tx = {
    id: generateUUID(),
    date: todayStr,
    time: timeStr,
    type: 'expense',
    category: tpl.category || 'Bills',
    amount: sanitizeFloat(parseFloat(tpl.amount) || 0),
    note: tpl.note || tpl.category || 'Recurring Payment',
    recurring_template_id: tpl.id,
    is_recurring: true,
    payment_method: tpl.payment_method || (state.accounts && state.accounts[0] ? state.accounts[0].name : 'Cash'),
    user_id: state.currentUser ? state.currentUser.id : null,
    family_id: (tpl.is_shared && state.currentFamilyId) ? state.currentFamilyId : null
  };

  if (!state.transactions) state.transactions = [];
  state.transactions.unshift(tx);
  localStorage.setItem('transactions', JSON.stringify(state.transactions));

  if (state.supabaseClient && state.currentUser) {
    state.supabaseClient.from('transactions').insert([tx])
      .catch(err => console.warn('Failed to insert quick-pay recurring transaction to cloud:', err));
  }

  if (typeof showToast === 'function') {
    showToast(state.lang === 'el' ? `✓ Καταχωρήθηκε η πληρωμή: ${tx.note}` : `✓ Payment logged: ${tx.note}`, 'success');
  }
  renderSubscriptionsHub();
  updateSafeToSpendUI();
  if (typeof updateUI === 'function') {
    updateUI();
  }
}
window.quickPaySubscription = quickPaySubscription;


// ============================================================
// FEATURE: AI FINANCIAL COACH CHAT LOGIC
// ============================================================

function openAdvisorChat(initialQuery = null) {
  const modalId = 'advisor-chat-modal';
  // Open the modal FIRST and unconditionally. Any error below must never prevent
  // the bottom sheet from appearing — otherwise the button appears "dead".
  try {
    openModal(modalId);
  } catch (e) {
    console.error('[AdvisorChat] openModal failed:', e);
    // Last-resort fallback: force the overlay visible even if openModal threw.
    const el = document.getElementById(modalId);
    if (el) {
      el.classList.add('active');
      document.body.classList.add('modal-open');
    }
  }

  try {
    // If we have an active conversation, load it; otherwise show the conversation list.
    // Guard against a stale active ID (points to a conversation that no longer exists,
    // e.g. after local storage was cleared or a conversation was removed). Without this,
    // openAdvisorConversation() returns early and the modal opens blank — appearing as
    // if the AI advisor "doesn't open".
    const activeId = getActiveAdvisorConversationId();
    const activeConv = activeId ? getActiveAdvisorConversation() : null;
    if (activeConv) {
      openAdvisorConversation(activeId, false);
    } else {
      // Clear any stale active ID so the next open starts fresh.
      if (activeId) setActiveAdvisorConversationId(null);
      showAdvisorConversationList();
    }
  } catch (e) {
    console.error('[AdvisorChat] conversation load failed:', e);
    // Ensure the conversation list is shown so the modal is never blank.
    try { showAdvisorConversationList(); } catch (e2) { console.error(e2); }
  }

  setTimeout(() => {
    // Skip auto-focus when restoring from background — keyboard would cause flicker
    if (window._appJustResumed) return;
    const inp = document.getElementById('advisor-chat-input');
    if (inp) inp.focus();
  }, 300);

  if (initialQuery) {
    setTimeout(() => {
      submitCoachQuery(initialQuery);
    }, 500);
  }
}

function closeAdvisorChat() {
  closeModal('advisor-chat-modal');
}

// ===== Advisor Chat Conversation History (persistent, ChatGPT-style) =====
const ADVISOR_CONVERSATIONS_KEY = 'advisor_chat_conversations_v1';
const ADVISOR_ACTIVE_KEY = 'advisor_chat_active_id_v1';

function loadAdvisorConversations() {
  try {
    const key = getUserScopedKey(ADVISOR_CONVERSATIONS_KEY);
    const raw = localStorage.getItem(key);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list : [];
  } catch (e) {
    console.warn('[AdvisorChat] Failed to load conversations:', e);
    return [];
  }
}

function saveAdvisorConversations(list) {
  try {
    const key = getUserScopedKey(ADVISOR_CONVERSATIONS_KEY);
    localStorage.setItem(key, JSON.stringify(list || []));
  } catch (e) {
    console.warn('[AdvisorChat] Failed to save conversations:', e);
  }
}

function getActiveAdvisorConversationId() {
  try {
    const key = getUserScopedKey(ADVISOR_ACTIVE_KEY);
    return localStorage.getItem(key) || null;
  } catch (e) {
    return null;
  }
}

function setActiveAdvisorConversationId(id) {
  try {
    const key = getUserScopedKey(ADVISOR_ACTIVE_KEY);
    if (id) localStorage.setItem(key, id);
    else localStorage.removeItem(key);
  } catch (e) { }
}

function getActiveAdvisorConversation() {
  const id = getActiveAdvisorConversationId();
  if (!id) return null;
  const list = loadAdvisorConversations();
  return list.find(c => c.id === id) || null;
}

function getConversationTitle(messages) {
  const firstUser = (messages || []).find(m => m.sender === 'user');
  if (firstUser && firstUser.html) {
    const plain = firstUser.html.replace(/<[^>]*>/g, '').trim();
    if (plain) return plain.length > 40 ? plain.slice(0, 40) + '…' : plain;
  }
  return state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation';
}

function showAdvisorConversationList() {
  const listEl = document.getElementById('advisor-conversation-list');
  const chatLog = document.getElementById('advisor-chat-log');
  const backBtn = document.getElementById('advisor-chat-back-btn');
  const newBtn = document.getElementById('advisor-chat-new-btn');
  const suggestions = document.getElementById('advisor-chat-suggestions-container');
  const inputArea = document.getElementById('advisor-chat-input');

  if (listEl) listEl.style.display = 'flex';
  if (chatLog) chatLog.style.display = 'none';
  if (backBtn) backBtn.style.display = 'none';
  if (newBtn) newBtn.style.display = 'none';
  if (suggestions) suggestions.style.display = 'none';
  if (inputArea) inputArea.disabled = true;

  renderAdvisorConversationList();
}

function renderAdvisorConversationList() {
  const listEl = document.getElementById('advisor-conversation-list');
  if (!listEl) return;
  listEl.innerHTML = '';

  const list = loadAdvisorConversations();

  // New conversation button at top
  const newCard = document.createElement('div');
  newCard.style.cssText = 'display:flex; align-items:center; gap:10px; padding:14px 16px; border-radius:14px; background:var(--accent); color:#fff; font-weight:700; cursor:pointer; font-size:14px;';
  newCard.innerHTML = `<span style="font-size:16px;">&#10133;</span> ${state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation'}`;
  newCard.onclick = () => startNewAdvisorConversation();
  listEl.appendChild(newCard);

  if (list.length === 0) {
    const empty = document.createElement('div');
    empty.style.cssText = 'text-align:center; color:var(--text-secondary); font-size:13px; padding:24px 12px;';
    empty.textContent = state.lang === 'el'
      ? 'Δεν υπάρχουν ακόμα συνομιλίες. Ξεκίνησε μία νέα!'
      : 'No conversations yet. Start a new one!';
    listEl.appendChild(empty);
    return;
  }

  // Sort by updatedAt descending (most recent first)
  const sorted = [...list].sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));

  sorted.forEach(conv => {
    const card = document.createElement('div');
    card.style.cssText = 'display:flex; align-items:center; gap:10px; padding:14px 16px; border-radius:14px; background:var(--bg-card); border:1px solid var(--border); cursor:pointer;';
    card.innerHTML = `
      <span style="font-size:16px; flex-shrink:0;">💬</span>
      <div style="flex:1; min-width:0;">
        <div style="font-weight:600; font-size:13.5px; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(conv.title || '')}</div>
        <div style="font-size:11px; color:var(--text-secondary); margin-top:2px;">${formatConversationTime(conv.updatedAt)}</div>
      </div>
      <span class="advisor-conv-delete" onclick="event.stopPropagation(); deleteAdvisorConversation('${conv.id}')" title="${state.lang === 'el' ? 'Διαγραφή' : 'Delete'}" style="cursor:pointer; font-size:15px; color:var(--text-secondary); flex-shrink:0; padding:4px;">&#128465;</span>
    `;
    card.onclick = () => openAdvisorConversation(conv.id);
    listEl.appendChild(card);
  });
}

function formatConversationTime(ts) {
  if (!ts) return '';
  try {
    const d = new Date(ts);
    return d.toLocaleString(state.lang === 'el' ? 'el-GR' : 'en-US', {
      day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'
    });
  } catch (e) {
    return '';
  }
}

function openAdvisorConversation(id, focusInput = true) {
  const list = loadAdvisorConversations();
  const conv = list.find(c => c.id === id);
  if (!conv) return;

  setActiveAdvisorConversationId(id);

  const listEl = document.getElementById('advisor-conversation-list');
  const chatLog = document.getElementById('advisor-chat-log');
  const backBtn = document.getElementById('advisor-chat-back-btn');
  const newBtn = document.getElementById('advisor-chat-new-btn');
  const suggestions = document.getElementById('advisor-chat-suggestions-container');
  const inputArea = document.getElementById('advisor-chat-input');

  if (listEl) listEl.style.display = 'none';
  if (chatLog) {
    chatLog.style.display = 'flex';
    chatLog.innerHTML = '';
  }
  if (backBtn) backBtn.style.display = 'flex';
  if (newBtn) newBtn.style.display = 'flex';
  if (suggestions) suggestions.style.display = 'block';
  if (inputArea) inputArea.disabled = false;

  // Restore messages
  (conv.messages || []).forEach(m => {
    appendChatMessage(m.sender, m.html, false);
  });

  // Restore Gemini context history
  if (Array.isArray(conv.geminiHistory)) {
    state.advisorChatHistory = conv.geminiHistory.slice();
  } else {
    state.advisorChatHistory = [];
  }

  if (focusInput) {
    setTimeout(() => {
      if (window._appJustResumed) return;
      const inp = document.getElementById('advisor-chat-input');
      if (inp) inp.focus();
    }, 300);
  }
}

function startNewAdvisorConversation() {
  const id = 'conv_' + Date.now() + '_' + Math.random().toString(36).substr(2, 8);
  const conv = {
    id,
    title: state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation',
    createdAt: Date.now(),
    updatedAt: Date.now(),
    messages: [],
    geminiHistory: []
  };
  const list = loadAdvisorConversations();
  list.push(conv);
  saveAdvisorConversations(list);
  setActiveAdvisorConversationId(id);

  // Clear the chat log and show welcome
  const chatLog = document.getElementById('advisor-chat-log');
  if (chatLog) chatLog.innerHTML = '';
  state.advisorChatHistory = [];

  const welcome = state.lang === 'el'
    ? "Γεια σου! Είμαι ο προσωπικός σου **Οικονομικός Σύμβουλος AI**. 🤖<br><br>Μπορώ να αναλύσω τις συναλλαγές σου και να σε βοηθήσω να αποταμιεύσεις περισσότερο. Επιλέξτε μία από τις παρακάτω προτάσεις ή ρωτήστε με ό,τι θέλετε!"
    : "Hello! I am your personal **AI Financial Coach**. 🤖<br><br>I can analyze your transactions and help you save more. Select one of the suggestions below or ask me anything!";
  appendChatMessage('advisor', welcome);

  // Switch view to chat
  const listEl = document.getElementById('advisor-conversation-list');
  const backBtn = document.getElementById('advisor-chat-back-btn');
  const newBtn = document.getElementById('advisor-chat-new-btn');
  const suggestions = document.getElementById('advisor-chat-suggestions-container');
  const inputArea = document.getElementById('advisor-chat-input');
  if (listEl) listEl.style.display = 'none';
  if (chatLog) chatLog.style.display = 'flex';
  if (backBtn) backBtn.style.display = 'flex';
  if (newBtn) newBtn.style.display = 'flex';
  if (suggestions) suggestions.style.display = 'block';
  if (inputArea) inputArea.disabled = false;

  setTimeout(() => {
    if (window._appJustResumed) return;
    const inp = document.getElementById('advisor-chat-input');
    if (inp) inp.focus();
  }, 300);
}

function deleteAdvisorConversation(id) {
  const list = loadAdvisorConversations();
  const idx = list.findIndex(c => c.id === id);
  if (idx === -1) return;

  const conv = list[idx];
  const confirmMsg = state.lang === 'el'
    ? `Να διαγραφεί η συνομιλία «${conv.title || ''}»;`
    : `Delete conversation "${conv.title || ''}"?`;

  if (!window.confirm(confirmMsg)) return;

  list.splice(idx, 1);
  saveAdvisorConversations(list);

  // If the deleted conversation was active, clear active state
  if (getActiveAdvisorConversationId() === id) {
    setActiveAdvisorConversationId(null);
    state.advisorChatHistory = [];
  }

  renderAdvisorConversationList();

  // Διαγραφή και από το cloud backup
  if (state.supabaseClient && state.currentUser) {
    state.supabaseClient
      .from('ai_conversations')
      .delete()
      .eq('id', id)
      .eq('user_id', state.currentUser.id)
      .then(res => {
        if (res && res.error) console.warn('[AdvisorSync] error deleting remote conversation:', res.error);
      }, err => console.warn('[AdvisorSync] delete remote conversation failed:', err));
  }
}

function persistAdvisorMessage(sender, htmlContent) {
  const id = getActiveAdvisorConversationId();
  if (!id) return;
  const list = loadAdvisorConversations();
  const conv = list.find(c => c.id === id);
  if (!conv) return;

  if (!Array.isArray(conv.messages)) conv.messages = [];
  conv.messages.push({ sender, html: htmlContent });
  conv.updatedAt = Date.now();
  // Set the title from the first user message (welcome message may come first)
  if (sender === 'user' && (!conv.title || conv.title === (state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation'))) {
    conv.title = getConversationTitle(conv.messages);
  }
  saveAdvisorConversations(list);
  scheduleAdvisorConversationSync();
}

function persistAdvisorGeminiHistory(history) {
  const id = getActiveAdvisorConversationId();
  if (!id) return;
  const list = loadAdvisorConversations();
  const conv = list.find(c => c.id === id);
  if (!conv) return;
  conv.geminiHistory = Array.isArray(history) ? history.slice() : [];
  conv.updatedAt = Date.now();
  saveAdvisorConversations(list);
  scheduleAdvisorConversationSync();
}

function updateAdvisorMessageSavedState(btnId) {
  try {
    const convId = getActiveAdvisorConversationId();
    if (!convId) return;
    const list = loadAdvisorConversations();
    const conv = list.find(c => c.id === convId);
    if (!conv || !Array.isArray(conv.messages)) return;

    let modified = false;
    const savedText = (state.lang === 'el') ? '✅ Καταχωρήθηκε!' : '✅ Saved!';
    const replacementBtn = `<button id="${btnId}" class="btn btn-success" disabled style="width:100%; padding: 12px; font-weight: 700; border-radius: 8px; background-color: var(--success); color: white; border: none; cursor: default; opacity: 0.9;">${savedText}</button>`;

    conv.messages.forEach(msg => {
      if (typeof msg.content === 'string' && msg.content.includes(btnId)) {
        msg.content = msg.content.replace(
          new RegExp(`<button[^>]*id=["']${btnId}["'][^>]*>[\\s\\S]*?<\\/button>`, 'i'),
          replacementBtn
        );
        modified = true;
      }
    });

    if (modified) {
      conv.updatedAt = Date.now();
      saveAdvisorConversations(list);
      scheduleAdvisorConversationSync();
    }
  } catch (err) {
    console.warn('[AdvisorChat] Failed to update message saved state:', err);
  }
}

// ============================================================
// AI Σύμβουλος — Cloud Sync (backup των συνομιλιών στο Supabase)
// ============================================================
// Οι συνομιλίες αποθηκεύονται τοπικά στο localStorage με κλειδί
// 'advisor_chat_conversations_v1'. Για να μην χάνονται όταν εκκαθαρίζεται
// το τοπικό storage (εκκαθάριση WebView, επανεγκατάσταση κ.λπ.),
// συγχρονίζονται και στον πίνακα public.ai_conversations (βλ.
// ai-conversations-migration.sql), με λογική merge-by-updatedAt,
// ακριβώς όπως οι σημειώσεις (syncNotes).
// ============================================================
let _advisorSyncTimer = null;

function scheduleAdvisorConversationSync() {
  if (_advisorSyncTimer) clearTimeout(_advisorSyncTimer);
  _advisorSyncTimer = setTimeout(() => { syncAdvisorConversations(); }, 800);
}

async function syncAdvisorConversations() {
  if (!state.supabaseClient || !state.currentUser) return;
  const userId = state.currentUser.id;

  try {
    const { data: remoteConvs, error } = await state.supabaseClient
      .from('ai_conversations')
      .select('*')
      .eq('user_id', userId);

    if (error) {
      if (error.code === 'PGRST116' || error.code === '42P01' || error.status === 404) {
        console.log('[AdvisorSync] ai_conversations table not found in database. Skipping cloud sync.');
        return;
      }
      console.warn('[AdvisorSync] error fetching remote conversations:', error);
      return;
    }

    const localList = loadAdvisorConversations();
    if (!Array.isArray(localList)) return;

    const remoteMap = new Map();
    (remoteConvs || []).forEach(rc => remoteMap.set(rc.id, rc));

    const mergedList = [];
    const convsToUpsert = [];

    localList.forEach(localConv => {
      const remoteConv = remoteMap.get(localConv.id);
      if (remoteConv) {
        const localDate = new Date(localConv.updatedAt || localConv.createdAt || 0);
        const remoteDate = new Date(remoteConv.updated_at || remoteConv.created_at || 0);
        if (localDate > remoteDate) {
          mergedList.push(localConv);
          convsToUpsert.push(localConv);
        } else {
          // Το cloud αντίγραφο είναι νεότερο — το υιοθετούμε τοπικά
          mergedList.push({
            id: remoteConv.id,
            title: remoteConv.title || (state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation'),
            createdAt: remoteConv.created_at ? new Date(remoteConv.created_at).getTime() : Date.now(),
            updatedAt: remoteConv.updated_at ? new Date(remoteConv.updated_at).getTime() : Date.now(),
            messages: Array.isArray(remoteConv.messages) ? remoteConv.messages : [],
            geminiHistory: Array.isArray(remoteConv.gemini_history) ? remoteConv.gemini_history : []
          });
        }
        remoteMap.delete(localConv.id);
      } else {
        mergedList.push(localConv);
        convsToUpsert.push(localConv);
      }
    });

    // Όσες υπάρχουν μόνο στο cloud, τις προσθέτουμε τοπικά
    remoteMap.forEach(rc => {
      mergedList.push({
        id: rc.id,
        title: rc.title || (state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation'),
        createdAt: rc.created_at ? new Date(rc.created_at).getTime() : Date.now(),
        updatedAt: rc.updated_at ? new Date(rc.updated_at).getTime() : Date.now(),
        messages: Array.isArray(rc.messages) ? rc.messages : [],
        geminiHistory: Array.isArray(rc.gemini_history) ? rc.gemini_history : []
      });
    });

    // Ταξινόμηση κατά updatedAt (νεότερα πρώτα) και αποθήκευση τοπικά
    mergedList.sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
    saveAdvisorConversations(mergedList);

    // Push τοπικών αλλαγών στο cloud
    if (convsToUpsert.length > 0) {
      const records = convsToUpsert.map(c => ({
        id: c.id,
        title: c.title || (state.lang === 'el' ? 'Νέα συνομιλία' : 'New conversation'),
        messages: Array.isArray(c.messages) ? c.messages : [],
        gemini_history: Array.isArray(c.geminiHistory) ? c.geminiHistory : [],
        user_id: userId,
        created_at: c.createdAt ? new Date(c.createdAt).toISOString() : new Date().toISOString(),
        updated_at: c.updatedAt ? new Date(c.updatedAt).toISOString() : new Date().toISOString()
      }));

      const { error: upsertError } = await state.supabaseClient
        .from('ai_conversations')
        .upsert(records);

      if (upsertError) {
        console.warn('[AdvisorSync] error pushing local conversations to remote:', upsertError);
      }
    }
  } catch (err) {
    console.warn('[AdvisorSync] unhandled exception during conversations sync:', err);
  }
}
window.syncAdvisorConversations = syncAdvisorConversations;

function appendChatMessage(sender, htmlContent, persist = true) {
  const chatLog = document.getElementById('advisor-chat-log');
  if (!chatLog) return;

  const row = document.createElement('div');
  row.className = `chat-msg-row ${sender}`;

  const bubble = document.createElement('div');
  bubble.className = 'chat-msg-bubble';
  if (sender === 'user') {
    bubble.textContent = htmlContent;
  } else {
    bubble.innerHTML = htmlContent.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  }

  row.appendChild(bubble);
  chatLog.appendChild(row);

  chatLog.scrollTop = chatLog.scrollHeight;

  if (persist) {
    persistAdvisorMessage(sender, htmlContent);
  }
}

function handleAdvisorChatInput(el) {
  if (!el) return;
  el.style.height = 'auto';
  const newHeight = Math.min(el.scrollHeight, 130);
  el.style.height = (newHeight > 44 ? newHeight : 44) + 'px';
}

function submitCoachInput() {
  const inp = document.getElementById('advisor-chat-input');
  if (!inp) return;
  const val = inp.value.trim();
  if (!val) return;
  inp.value = '';
  inp.style.height = '44px';
  submitCoachQuery(val);
}

function handleAdvisorChatKeydown(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    submitCoachInput();
  }
}

function submitCoachQuery(queryText) {
  let userDisplay = queryText;
  let actualQuery = queryText;
  if (queryText === 'overspending') {
    userDisplay = state.lang === 'el' ? "Πού ξοδεύω υπερβολικά;" : "Where am I overspending?";
    actualQuery = userDisplay;
  } else if (queryText === 'savings') {
    userDisplay = state.lang === 'el' ? "Πώς μπορώ να αποταμιεύσω περισσότερο;" : "How can I save more?";
    actualQuery = userDisplay;
  } else if (queryText === 'forecast_5y') {
    userDisplay = state.lang === 'el' ? "Αν συνεχίσω έτσι, πού θα είμαι σε 5 χρόνια;" : "If I continue like this, where will I be in 5 years?";
    actualQuery = userDisplay;
  } else if (queryText === 'milestone_50k' || queryText === 'milestone_50000') {
    userDisplay = state.lang === 'el' ? "Πότε θα φτάσω τα 50.000€;" : "When will I reach €50,000?";
    actualQuery = userDisplay;
  } else if (queryText.startsWith('milestone_')) {
    let amtStr = queryText.replace('milestone_', '');
    let num = amtStr.endsWith('k') ? (parseFloat(amtStr) * 1000) : (parseInt(amtStr, 10) || 50000);
    userDisplay = state.lang === 'el' ? `Πότε θα φτάσω τα ${formatCurrency(num)};` : `When will I reach ${formatCurrency(num)}?`;
    actualQuery = userDisplay;
  }

  // Ensure an active conversation exists (e.g. when a suggestion chip is tapped from the list view)
  if (!getActiveAdvisorConversationId()) {
    startNewAdvisorConversation();
  }

  appendChatMessage('user', userDisplay);

  const suggestions = document.getElementById('advisor-chat-suggestions-container');
  if (suggestions) suggestions.style.display = 'none';

  const chatLog = document.getElementById('advisor-chat-log');
  const typingIndicatorRow = document.createElement('div');
  typingIndicatorRow.className = 'chat-msg-row advisor typing-temp';
  typingIndicatorRow.innerHTML = `
    <div class="chat-msg-bubble">
      <div class="chat-typing-indicator">
        <div class="chat-typing-dot"></div>
        <div class="chat-typing-dot"></div>
        <div class="chat-typing-dot"></div>
      </div>
    </div>
  `;
  if (chatLog) {
    chatLog.appendChild(typingIndicatorRow);
    chatLog.scrollTop = chatLog.scrollHeight;
  }

  // Execute immediately without artificial delays
  (async () => {
    // 1. Check if we should use Online AI (Gemini)
    const norm = normalizeGreekString(actualQuery);
    const isLocalReport = norm.includes('προϋπολογισμ') || norm.includes('οριο') || norm.includes('ορια') || norm.includes('που ξοδευω τα περισσοτερα') || norm.includes('που ξοδευω τα') || norm.includes('που πανε τα λεφτα') || norm.includes('μεγαλυτερα εξοδα') || norm.includes('top spending');

    // Premium gate: only ONLINE advisor calls count toward the fair-use limit.
    // If the user is at their limit, skip the online call and fall through to
    // the free offline NLP fallback below (never leave the user without an answer).
    const aiAllowed = (!isLocalReport && window.OnlineAIProvider)
      ? await canUseOnlineAI()
      : false;

    if (aiAllowed) {
      try {
        const pacing = getCoachAveragePacing();
        const currentMonth = new Date().getMonth();
        const currentYear = new Date().getFullYear();

        // Calculate this month's stats
        const thisMonthTrans = (state.transactions || []).filter(t => {
          if (!t.date || isTransferTransaction(t)) return false;
          const datePart = String(t.date).split('T')[0];
          const parts = datePart.split('-');
          if (parts.length !== 3) return false;
          return parseInt(parts[0], 10) === currentYear && (parseInt(parts[1], 10) - 1) === currentMonth;
        });

        let thisMonthIncome = 0;
        let thisMonthExpense = 0;
        thisMonthTrans.forEach(t => {
          const amt = CurrencyService.toBase(t);
          if (t.type === 'income') thisMonthIncome += amt;
          if (t.type === 'expense') thisMonthExpense += amt;
        });

        // Map simplified allTransactions to save tokens.
        // IMPORTANT: The online AI endpoint enforces a 64 KB request-body limit
        // (see functions/api/_security.js validateRequest). Sending the ENTIRE
        // transaction history can exceed that limit and cause a 413
        // "Request body too large" error, forcing a fallback to the local system.
        // To stay within the limit we (a) cap the number of raw transactions sent
        // to the most recent MAX_AI_TX (enough for specific lookups / edits),
        // (b) truncate long note fields, and (c) as a final safety net, trim the
        // array until the serialized stats payload fits under the server limit.
        //
        // CRITICAL: Because raw transactions are capped, the AI could NOT answer
        // "all-time" questions (e.g. "how much did I spend on groceries overall?")
        // from the raw list alone. To preserve full-history coverage we ALSO send
        // pre-aggregated summaries computed over the ENTIRE history (all months,
        // all categories, all years) in a tiny payload. The AI uses these
        // aggregates for any question spanning more than the recent window.
        const MAX_AI_TX = 400;
        const MAX_AI_NOTE_LEN = 60;
        const AI_BODY_BUDGET = 40 * 1024; // 40 KB headroom (server allows 64 KB)

        const rawTxs = (state.transactions || []).slice();
        // Newest first so the most relevant/recent history is preserved when we cap.
        rawTxs.sort((a, b) => {
          const da = String(a.date || '').split('T')[0].split(' ')[0];
          const db = String(b.date || '').split('T')[0].split(' ')[0];
          return db.localeCompare(da);
        });

        let allTransactions = rawTxs.slice(0, MAX_AI_TX).map(t => {
          const note = (t.note || t.description || '').trim();
          return {
            id: t.id,
            date: String(t.date || '').split('T')[0].split(' ')[0],
            type: t.type,
            amount: CurrencyService.toBase(t),
            category: t.category || '',
            subcategory: t.subcategory || '',
            note: note.length > MAX_AI_NOTE_LEN ? note.slice(0, MAX_AI_NOTE_LEN) : note
          };
        });

        // Map simplified accounts
        const accounts = (state.accounts || []).map(a => ({
          name: a.name || '',
          type: a.type || '',
          balance: parseFloat(a.balance) || 0
        }));

        const today = new Date();
        const currentDate = today.toISOString().split('T')[0];

        // ---- Full-history aggregates (computed over ALL transactions) ----
        // These let the AI answer "all-time" / "this year" / "per category"
        // questions accurately even though raw transactions are capped.
        const allRawTxs = state.transactions || [];
        const monthAgg = {};   // key: "YYYY-MM" -> { income, expense }
        const catAgg = {};     // key: category -> { income, expense }
        const yearAgg = {};    // key: "YYYY" -> { income, expense }
        const subcatAgg = {};  // key: "category|subcategory" -> { expense }

        allRawTxs.forEach(t => {
          if (!t.date || isTransferTransaction(t)) return;
          const datePart = String(t.date).split('T')[0].split(' ')[0];
          const parts = datePart.split('-');
          if (parts.length !== 3) return;
          const year = parts[0];
          const monthKey = `${year}-${parts[1]}`;
          const amt = CurrencyService.toBase(t);
          const isIncome = t.type === 'income';
          const isExpense = t.type === 'expense';
          if (!isIncome && !isExpense) return;

          if (!monthAgg[monthKey]) monthAgg[monthKey] = { income: 0, expense: 0 };
          if (!yearAgg[year]) yearAgg[year] = { income: 0, expense: 0 };
          if (isIncome) {
            monthAgg[monthKey].income += amt;
            yearAgg[year].income += amt;
          } else {
            monthAgg[monthKey].expense += amt;
            yearAgg[year].expense += amt;
          }

          const cat = t.category || '';
          if (cat) {
            if (!catAgg[cat]) catAgg[cat] = { income: 0, expense: 0 };
            if (isIncome) catAgg[cat].income += amt;
            else catAgg[cat].expense += amt;
          }
          const subcat = t.subcategory || '';
          if (cat && subcat) {
            const key = `${cat}|${subcat}`;
            if (!subcatAgg[key]) subcatAgg[key] = { expense: 0 };
            if (isExpense) subcatAgg[key].expense += amt;
          }
        });

        const currentYearStr = String(currentYear);
        const ytdIncome = yearAgg[currentYearStr]?.income || 0;
        const ytdExpense = yearAgg[currentYearStr]?.expense || 0;
        const ytdNetBalance = ytdIncome - ytdExpense;

        const currentSafeToSpend = (typeof SafeToSpendEngine !== 'undefined')
          ? SafeToSpendEngine.calculateDailySafeToSpend({
              currentBalance: getLiquidBalance(),
              unpaidRecurringBills: getUnpaidRecurringBillsThisMonth(),
              savingsGoal: getMonthlySavingsGoal()
            })
          : null;

        const stats = {
          lang: state.lang,
          currentDate,
          thisMonthIncome,
          thisMonthExpense,
          currentBalance: pacing.totalBalance || 0,
          safeToSpend: currentSafeToSpend,
          averageMonthlyIncome: pacing.avgIncome || 0,
          averageMonthlyExpense: pacing.avgExpense || 0,
          averageMonthlyNetSavings: (pacing.avgIncome || 0) - (pacing.avgExpense || 0),
          ytdCurrentYearIncome: ytdIncome,
          ytdCurrentYearExpense: ytdExpense,
          ytdCurrentYearNetBalance: ytdNetBalance,
          budgets: state.budgets || {},
          accounts,
          allTransactions,
          // Full-history aggregates (entire history, not capped):
          monthlyTotals: monthAgg,
          yearlyTotals: yearAgg,
          categoryTotals: catAgg,
          subcategoryTotals: subcatAgg
        };

        // Final safety net: if the serialized stats payload is still too large
        // (e.g. an enormous budgets object or very long history), trim the
        // transaction array until it fits under the budget. This guarantees the
        // request never trips the server's 64 KB body guard. The full-history
        // aggregates above are tiny and are NOT trimmed, so all-time questions
        // remain answerable even after raw transactions are reduced.
        while (allTransactions.length > 0 && JSON.stringify(stats).length > AI_BODY_BUDGET) {
          allTransactions = allTransactions.slice(0, Math.floor(allTransactions.length / 2));
          stats.allTransactions = allTransactions;
        }

        if (!state.advisorChatHistory) {
          state.advisorChatHistory = [];
        }
        // Defensive cap on the conversation history sent to the online AI so the
        // request body stays well under the server's 64 KB limit even if a large
        // history was loaded from a persisted conversation.
        const advisorHistory = state.advisorChatHistory.slice(-12);
        const data = await window.OnlineAIProvider.processAdvisorQuery(actualQuery, stats, advisorHistory);

        // Remove typing indicator AFTER fetch completes
        const temp = document.querySelector('.typing-temp');
        if (temp) temp.remove();

        if (data && data.error) {
          console.warn('[AIEngine] Online Advisor returned error:', data.error);
          if (data.error.includes('GEMINI_API_KEY')) {
            const msg = state.lang === 'el'
              ? `⚠️ **Ο Οικονομικός Σύμβουλος AI δεν έχει ρυθμιστεί ακόμα.**<br><br>Παρακαλώ προσθέστε τη μεταβλητή περιβάλλοντος **GEMINI_API_KEY** στις ρυθμίσεις του project σας στο Cloudflare Pages και κάντε ξανά deploy.`
              : `⚠️ **AI Financial Advisor is not configured yet.**<br><br>Please add the **GEMINI_API_KEY** environment variable in your Cloudflare Pages project settings and redeploy.`;
            appendChatMessage('advisor', msg);
            if (suggestions) suggestions.style.display = 'block';
            return;
          } else {
            // Tell the user the AI failed instead of silently falling back
            const lang = state.lang || 'el';
            const msg = lang === 'el'
              ? `⚠️ **Ο Online AI Σύμβουλος αντιμετώπισε πρόβλημα:**<br><br> ${data.error}<br><br><em>(Προσωρινή χρήση τοπικού συστήματος...)</em>`
              : `⚠️ **Online AI Advisor encountered an issue:**<br><br> ${data.error}<br><br><em>(Falling back to local system...)</em>`;
            appendChatMessage('advisor', msg);
            // DO NOT return here, so it falls through to offline fallback but with the warning visible!
          }
        }

        if (data && data.responseHtml) {
          appendChatMessage('advisor', data.responseHtml);

          // Append to history
          state.advisorChatHistory.push({ role: 'user', content: actualQuery });
          state.advisorChatHistory.push({ role: 'model', content: data.responseHtml });
          if (state.advisorChatHistory.length > 12) {
            state.advisorChatHistory = state.advisorChatHistory.slice(-12);
          }
          // Persist Gemini context to the active conversation
          persistAdvisorGeminiHistory(state.advisorChatHistory);
          const isExplicitAddIntent = data.classifiedIntent === 'add_transaction' || (function () {
            const nq = normalizeGreekString(actualQuery);
            const hasAddVerb = nq.includes('βαλε') || nq.includes('προσθεσε') || nq.includes('καταχωρησε') || nq.includes('χρεωσε') || nq.includes('πληρωσα') || nq.includes('ξοδεψα') || nq.startsWith('add ') || nq.includes('spent ');
            const isQuestion = nq.includes('ποτε') || nq.includes('ποσα') || nq.includes('ποσο') || nq.includes('θα φτασω') || nq.includes('θα εχω') || nq.includes('when') || nq.includes('how much');
            return hasAddVerb && !isQuestion;
          })();

          if (isExplicitAddIntent && data.transactionsToAdd && Array.isArray(data.transactionsToAdd)) {
            data.transactionsToAdd.forEach(tx => {
              if (tx.amount && tx.amount > 0) {
                const txHtml = runCoachTransactionEntry(tx.amount, tx.note || '', tx.type || 'expense', tx.category, tx.subcategory, tx.account_from, tx.date);
                appendChatMessage('advisor', txHtml);
              }
            });
          }

          if (data.transactionsToUpdate && Array.isArray(data.transactionsToUpdate)) {
            data.transactionsToUpdate.forEach(tx => {
              if (tx.id) {
                const existing = state.transactions.find(t => t.id === tx.id) || {};
                const amountVal = tx.amount !== undefined ? tx.amount : (existing.amount || 0);
                const noteVal = tx.note !== undefined ? tx.note : (existing.note || '');
                const typeVal = tx.type || existing.type || 'expense';
                const catVal = tx.category || existing.category || null;
                const subcatVal = tx.subcategory || existing.subcategory || null;
                const accVal = tx.account_from || existing.account_from || null;
                const dateVal = tx.date || existing.date || null;

                const txHtml = runCoachTransactionEntry(
                  amountVal,
                  noteVal,
                  typeVal,
                  catVal,
                  subcatVal,
                  accVal,
                  dateVal,
                  tx.id
                );
                appendChatMessage('advisor', txHtml);
              }
            });
          }

          if (data.transactionsToDelete && Array.isArray(data.transactionsToDelete)) {
            data.transactionsToDelete.forEach(id => {
              const existing = state.transactions.find(t => t.id === id);
              if (existing) {
                deleteTransaction(id);
                const msg = state.lang === 'el'
                  ? `🗑️ Η συναλλαγή **"${existing.note}" (${existing.amount}€)** διαγράφηκε επιτυχώς!`
                  : `🗑️ Transaction **"${existing.note}" (${existing.amount}€)** deleted successfully!`;
                appendChatMessage('advisor', msg);
              }
            });
          }

          // ONLINE-TO-OFFLINE LEARNING LOOP
          if (data.classifiedIntent && data.classifiedIntent !== 'unknown' && data.alternativePhrasings && Array.isArray(data.alternativePhrasings)) {
            if (window.IntentCorpus && window.IntentCorpus.learnFromGemini) {
              const count = window.IntentCorpus.learnFromGemini(data.classifiedIntent, data.alternativePhrasings);
            }
          }
          if (data.extractedEntities && Array.isArray(data.extractedEntities)) {
            if (window.KnowledgeGraph && window.KnowledgeGraph.learnFromGeminiEntities) {
              const res = window.KnowledgeGraph.learnFromGeminiEntities(data.extractedEntities);
            }
          }

          if (suggestions) suggestions.style.display = 'block';
          return;
        }
      } catch (err) {
        console.warn('[AIEngine] Online Advisor failed. Falling back to offline engine:', err);
      }
    }

    // Remove typing indicator for offline fallback
    const temp = document.querySelector('.typing-temp');
    if (temp) temp.remove();

    // 2. Offline Fallback
    const responseHtml = processCoachQuery(actualQuery);
    appendChatMessage('advisor', responseHtml);

    if (suggestions) suggestions.style.display = 'block';
  })();
}

function getCoachAveragePacing() {
  const trans = state.transactions || [];
  const monthlyData = {};

  trans.forEach(t => {
    if (!t.date || isTransferTransaction(t)) return;
    const datePart = String(t.date).split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10);
    const key = `${y}-${String(m).padStart(2, '0')}`;
    const amt = CurrencyService.toBase(t);

    if (!monthlyData[key]) {
      monthlyData[key] = { income: 0, expense: 0 };
    }
    if (t.type === 'income') monthlyData[key].income += amt;
    if (t.type === 'expense') monthlyData[key].expense += amt;
  });

  const keys = Object.keys(monthlyData).sort();
  if (keys.length === 0) {
    return { avgIncome: 0, avgExpense: 0, avgSavings: 0, totalBalance: 0 };
  }

  const lastKeys = keys.slice(-3);
  let sumIncome = 0;
  let sumExpense = 0;
  lastKeys.forEach(k => {
    sumIncome += monthlyData[k].income;
    sumExpense += monthlyData[k].expense;
  });

  const monthsCount = lastKeys.length;
  const avgIncome = sumIncome / monthsCount;
  const avgExpense = sumExpense / monthsCount;
  const avgSavings = avgIncome - avgExpense;

  const totalBalance = (state.accounts || []).reduce((sum, acc) => sum + (parseFloat(acc.balance) || 0), 0);

  return { avgIncome, avgExpense, avgSavings, totalBalance };
}

function runCoachOverspendingAnalysis() {
  const today = new Date();
  const currYear = today.getFullYear();
  const currMonth = today.getMonth();

  const currMonthExpenses = {};
  const prevExpenses = {};
  const monthsSeen = new Set();

  const trans = state.transactions || [];
  trans.forEach(t => {
    if (t.type !== 'expense' || !t.date) return;
    const datePart = String(t.date).split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const amt = CurrencyService.toBase(t);
    const cat = t.category || 'Other';

    if (y === currYear && m === currMonth) {
      currMonthExpenses[cat] = (currMonthExpenses[cat] || 0) + amt;
    } else {
      const diffMonths = (currYear - y) * 12 + (currMonth - m);
      if (diffMonths > 0 && diffMonths <= 3) {
        monthsSeen.add(`${y}-${m}`);
        if (!prevExpenses[cat]) prevExpenses[cat] = {};
        const monthKey = `${y}-${m}`;
        prevExpenses[cat][monthKey] = (prevExpenses[cat][monthKey] || 0) + amt;
      }
    }
  });

  const numPrevMonths = Math.max(1, monthsSeen.size);
  const overspentCats = [];

  Object.keys(currMonthExpenses).forEach(cat => {
    const currAmt = currMonthExpenses[cat] || 0;
    let sumPrev = 0;
    if (prevExpenses[cat]) {
      Object.keys(prevExpenses[cat]).forEach(mk => {
        sumPrev += prevExpenses[cat][mk];
      });
    }
    const avgPrev = sumPrev / numPrevMonths;
    const diff = currAmt - avgPrev;

    if (diff > 0) {
      const pct = avgPrev > 0 ? Math.round((diff / avgPrev) * 100) : 100;
      overspentCats.push({ cat, currAmt, avgPrev, diff, pct });
    }
  });

  overspentCats.sort((a, b) => b.diff - a.diff);

  if (overspentCats.length === 0) {
    return state.lang === 'el'
      ? "✅ **Όλα υπό έλεγχο!** Δεν εντοπίστηκε υπέρβαση εξόδων σε καμία κατηγορία αυτόν τον μήνα σε σχέση με τους προηγούμενους. Συνέχισε την εξαιρετική δουλειά! 👏"
      : "✅ **All under control!** No overspending was detected in any category this month compared to previous months. Keep up the great work! 👏";
  }

  let html = state.lang === 'el'
    ? "⚠️ **Εντοπίστηκε υπέρβαση εξόδων στις εξής κατηγορίες:**<br><br>"
    : "⚠️ **Overspending detected in the following categories:**<br><br>";

  overspentCats.slice(0, 3).forEach(item => {
    const dispCat = getCategoryDisplayName(item.cat);
    const pctStr = item.avgPrev > 0 ? ` (+${item.pct}%)` : ' (νέο έξοδο)';
    html += `• **${dispCat}**: Ξόδεψες **${formatCurrency(item.currAmt)}** αυτόν τον μήνα, ενώ ο προηγούμενος μέσος όρος σου ήταν **${formatCurrency(item.avgPrev)}**.<br>&nbsp;&nbsp;&nbsp;&nbsp;📈 Αύξηση: **+${formatCurrency(item.diff)}**${pctStr}.<br>`;
  });

  html += state.lang === 'el'
    ? "<br>💡 *Συμβουλή: Πατήστε στο κουμπί 'Συζήτησέ το' δίπλα από την κατηγορία στην κάρτα του συμβούλου για να δεις ποιες συναλλαγές προκάλεσαν την αύξηση.*"
    : "<br>💡 *Tip: Tap the 'Discuss it' button next to the category in the advisor card to see which transactions caused the increase.*";

  return html;
}

function runCoachSavingsAdvice() {
  const today = new Date();
  const currYear = today.getFullYear();
  const currMonth = today.getMonth();

  const nonEssentials = ['SUPERMARKET', 'MARKET', 'FOOD', 'ΔΙΑΤΡΟΦΗ', 'ΔΙΑΣΚΕΔΑΣΗ', 'ΕΞΟΔΟΙ', 'ENTERTAINMENT', 'LEISURE', 'SHOPPING', 'CLOTHES', 'ΠΡΟΣΩΠΙΚΗ', 'ΦΡΟΝΤΙΔΑ', 'PERSONAL', 'ΤΕΧΝΟΛΟΓΙΑ', 'TECH', 'GADGET', 'ΣΥΝΔΡΟΜΕΣ', 'SUBSCRIPTION'];

  const trans = state.transactions || [];
  const catTotals = {};

  trans.forEach(t => {
    if (t.type !== 'expense' || !t.date) return;
    const datePart = String(t.date).split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const amt = CurrencyService.toBase(t);

    if (y === currYear && m === currMonth) {
      const cat = t.category || 'Other';
      catTotals[cat] = (catTotals[cat] || 0) + amt;
    }
  });

  const matches = [];
  Object.keys(catTotals).forEach(cat => {
    const clean = cat.replace(/[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF]/g, '').trim().toUpperCase();
    const isNonEssential = nonEssentials.some(keyword => clean.includes(keyword));
    if (isNonEssential && catTotals[cat] > 20) {
      matches.push({ cat, amt: catTotals[cat] });
    }
  });

  matches.sort((a, b) => b.amt - a.amt);

  if (matches.length === 0) {
    return state.lang === 'el'
      ? "🎯 **Εξαιρετική οικονομία!** Δεν ξοδεύεις υπερβολικά σε προαιρετικά έξοδα αυτόν τον μήνα. Για να αποταμιεύσεις ακόμα περισσότερο, σκέψου να θέσεις έναν αυτόματο στόχο αποταμίευσης στην αρχή του μήνα."
      : "🎯 **Great economy!** You aren't spending excessively on discretionary categories this month. To save even more, consider setting an automatic savings goal at the start of the month.";
  }

  let html = state.lang === 'el'
    ? "💡 **Ιδέες για να αυξήσεις την αποταμίευσή σου άμεσα:**<br><br>"
    : "💡 **Ideas to boost your savings immediately:**<br><br>";

  matches.slice(0, 2).forEach(item => {
    const dispCat = getCategoryDisplayName(item.cat);
    const save10 = item.amt * 0.1;
    const save20 = item.amt * 0.2;

    html += state.lang === 'el'
      ? `• **${dispCat}**: Έχεις ξοδέψει **${formatCurrency(item.amt)}** αυτόν τον μήνα.<br>&nbsp;&nbsp;&nbsp;&nbsp;📉 Μείωση 10%: Κέρδος **+${formatCurrency(save10)}** / μήνα (€${Math.round(save10 * 12)}/έτος).<br>&nbsp;&nbsp;&nbsp;&nbsp;📉 Μείωση 20%: Κέρδος **+${formatCurrency(save20)}** / μήνα (€${Math.round(save20 * 12)}/έτος).<br>`
      : `• **${dispCat}**: You spent **${formatCurrency(item.amt)}** this month.<br>&nbsp;&nbsp;&nbsp;&nbsp;📉 Cut 10%: Saves **+${formatCurrency(save10)}** / month (€${Math.round(save10 * 12)}/year).<br>&nbsp;&nbsp;&nbsp;&nbsp;📉 Cut 20%: Saves **+${formatCurrency(save20)}** / month (€${Math.round(save20 * 12)}/year).<br>`;
  });

  html += state.lang === 'el'
    ? "<br>⚡ *Tip: Μπορείς να ορίσεις Budgets για αυτές τις κατηγορίες ώστε να λαμβάνεις ειδοποίηση μόλις πλησιάσεις το όριο!*"
    : "<br>⚡ *Tip: You can set Budgets for these categories to receive alerts when you approach your limit!*";

  return html;
}

function runCoachFiveYearForecast() {
  const pacing = getCoachAveragePacing();
  const startBalance = pacing.totalBalance;
  const monthlySavings = pacing.avgSavings;

  let html = "";
  if (state.lang === 'el') {
    html += `📈 **Πρόβλεψη Εξέλιξης 5ετίας:**<br><br>`;
    html += `• Τρέχον Υπόλοιπο: **${formatCurrency(startBalance)}**<br>`;
    html += `• Μέση Μηνιαία Αποταμίευση: **${formatCurrency(monthlySavings)}**/μήνα<br><br>`;

    if (monthlySavings <= 0) {
      html += `⚠️ **Προσοχή!** Ο μέσος ρυθμός αποταμίευσής σου είναι αρνητικός ή μηδενικός. Αν συνεχίσεις έτσι, η περιουσία σου δεν θα αυξηθεί και ενδέχεται να έχεις απώλειες. Προσπάθησε να μειώσεις τα έξοδά σου.`;
      return html;
    }

    for (let year = 1; year <= 5; year++) {
      const projected = startBalance + (year * 12 * monthlySavings);
      html += `• **Έτος ${year}**: ${formatCurrency(projected)} (+${formatCurrency(year * 12 * monthlySavings)})<br>`;
    }
    html += `<br>🔮 *Οι υπολογισμοί βασίζονται στον μέσο ρυθμό αποταμίευσης των τελευταίων 3 μηνών.*`;
  } else {
    html += `📈 **5-Year Financial Projection:**<br><br>`;
    html += `• Current Balance: **${formatCurrency(startBalance)}**<br>`;
    html += `• Average Monthly Savings: **${formatCurrency(monthlySavings)}**/month<br><br>`;

    if (monthlySavings <= 0) {
      html += `⚠️ **Warning!** Your average monthly savings rate is negative or zero. If this continues, your net worth will not grow and you might experience losses. Try to reduce your spending.`;
      return html;
    }

    for (let year = 1; year <= 5; year++) {
      const projected = startBalance + (year * 12 * monthlySavings);
      html += `• **Year ${year}**: ${formatCurrency(projected)} (+${formatCurrency(year * 12 * monthlySavings)})<br>`;
    }
    html += `<br>🔮 *Projections are based on your average savings rate from the last 3 months.*`;
  }

  return html;
}

function runCoachTargetMilestone(targetAmount = 50000) {
  const pacing = getCoachAveragePacing();
  const startBalance = pacing.totalBalance;
  const monthlySavings = pacing.avgSavings;

  let html = "";
  if (state.lang === 'el') {
    html += `🎯 **Ανάλυση Στόχου: ${formatCurrency(targetAmount)}**<br><br>`;
    html += `• Τρέχον Υπόλοιπο: **${formatCurrency(startBalance)}**<br>`;
    html += `• Υπολειπόμενο Ποσό: **${formatCurrency(Math.max(0, targetAmount - startBalance))}**<br>`;

    if (startBalance >= targetAmount) {
      return `🎉 **Συγχαρητήρια!** Έχεις ήδη επιτύχει αυτόν τον στόχο! Το τρέχον υπόλοιπό σου είναι **${formatCurrency(startBalance)}**.`;
    }

    if (monthlySavings <= 0) {
      return `⚠️ **Αδύνατη Πρόβλεψη**: Με τον τρέχοντα μέσο ρυθμό αποταμίευσής σου (**${formatCurrency(monthlySavings)}**/μήνα), δεν είναι δυνατή η επίτευξη του στόχου. Χρειάζεται να αυξήσεις τη μηνιαία αποταμίευσή σου για να ξεκινήσει η πρόοδος.`;
    }

    const months = Math.ceil((targetAmount - startBalance) / monthlySavings);
    const targetDate = new Date();
    targetDate.setMonth(targetDate.getMonth() + months);
    const dateStr = targetDate.toLocaleDateString('el-GR', { month: 'long', year: 'numeric' });

    html += `• Εκτιμώμενος Χρόνος: **${months} μήνες**<br>`;
    html += `• Ημερομηνία Επίτευξης: **${dateStr}**<br><br>`;
    html += `💡 *Συμβουλή: Αν αυξήσεις την αποταμίευσή σου κατά **€100/μήνα**, θα φτάσεις τον στόχο **${Math.max(1, Math.round(months - ((targetAmount - startBalance) / (monthlySavings + 100))))} μήνες νωρίτερα**!*`;
  } else {
    html += `🎯 **Target Analysis: ${formatCurrency(targetAmount)}**<br><br>`;
    html += `• Current Balance: **${formatCurrency(startBalance)}**<br>`;
    html += `• Remaining Amount: **${formatCurrency(Math.max(0, targetAmount - startBalance))}**<br>`;

    if (startBalance >= targetAmount) {
      return `🎉 **Congratulations!** You have already reached this target! Your current balance is **${formatCurrency(startBalance)}**.`;
    }

    if (monthlySavings <= 0) {
      return `⚠️ **Projection Impossible**: With your current average monthly savings rate (**${formatCurrency(monthlySavings)}**/month), you cannot reach this target. You need to increase your savings rate to make progress.`;
    }

    const months = Math.ceil((targetAmount - startBalance) / monthlySavings);
    const targetDate = new Date();
    targetDate.setMonth(targetDate.getMonth() + months);
    const dateStr = targetDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

    html += `• Estimated Time: **${months} months**<br>`;
    html += `• Milestone Date: **${dateStr}**<br><br>`;
    html += `💡 *Tip: If you increase your savings by **€100/month**, you will reach your goal **${Math.max(1, Math.round(months - ((targetAmount - startBalance) / (monthlySavings + 100))))} months faster**!*`;
  }

  return html;
}

function runCoachCategoryAnalysis(categoryName) {
  const today = new Date();
  const currYear = today.getFullYear();
  const currMonth = today.getMonth();

  const trans = state.transactions || [];
  const currMonthTrans = trans.filter(t => {
    if (t.type !== 'expense' || !t.date) return false;
    const datePart = String(t.date).split('T')[0].split(' ')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return false;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;

    const cleanT = t.category.replace(/[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF]/g, '').trim().toLowerCase();
    const cleanQuery = categoryName.replace(/[\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF]/g, '').trim().toLowerCase();

    return y === currYear && m === currMonth && (cleanT.includes(cleanQuery) || cleanQuery.includes(cleanT));
  });

  if (currMonthTrans.length === 0) {
    return state.lang === 'el'
      ? `Δεν βρήκα έξοδα στην κατηγορία **${categoryName}** για αυτόν τον μήνα.`
      : `No expenses found in the **${categoryName}** category for this month.`;
  }

  const totalAmt = currMonthTrans.reduce((sum, t) => sum + CurrencyService.toBase(t), 0);
  const top3 = currMonthTrans.sort((a, b) => (parseFloat(b.amount) || 0) - (parseFloat(a.amount) || 0)).slice(0, 3);

  let html = "";
  if (state.lang === 'el') {
    html += `📋 **Ανάλυση Εξόδων κατηγορίας: ${categoryName}**<br><br>`;
    html += `• Συνολικά έξοδα μήνα: **${formatCurrency(totalAmt)}**<br>`;
    html += `• Πλήθος συναλλαγών: **${currMonthTrans.length}**<br><br>`;
    html += `🔍 **Οι 3 μεγαλύτερες συναλλαγές:**<br>`;

    top3.forEach((t, idx) => {
      const dateObj = new Date(t.date);
      const formattedDate = dateObj.toLocaleDateString('el-GR', { day: '2-digit', month: '2-digit' });
      const translatedSub = getSubcategoryDisplayName(t.subcategory, t.category);
      const translatedCat = getCategoryDisplayName(t.category);
      const displayTitle = (t.note && t.note.trim()) ? t.note.trim()
        : (t.description && t.description.trim()) ? t.description.trim()
          : (translatedSub && translatedSub.trim()) ? translatedSub.trim()
            : (translatedCat || '');

      html += `${idx + 1}. **${formattedDate}**: ${escapeHtml(displayTitle)} — **${formatCurrency(t.amount)}**<br>`;
    });
  } else {
    html += `📋 **Expense Analysis for: ${categoryName}**<br><br>`;
    html += `• Total monthly expenses: **${formatCurrency(totalAmt)}**<br>`;
    html += `• Total transactions count: **${currMonthTrans.length}**<br><br>`;
    html += `🔍 **Top 3 largest transactions:**<br>`;

    top3.forEach((t, idx) => {
      const dateObj = new Date(t.date);
      const formattedDate = dateObj.toLocaleDateString('en-US', { day: '2-digit', month: '2-digit' });
      const translatedSub = getSubcategoryDisplayName(t.subcategory, t.category);
      const translatedCat = getCategoryDisplayName(t.category);
      const displayTitle = (t.note && t.note.trim()) ? t.note.trim()
        : (t.description && t.description.trim()) ? t.description.trim()
          : (translatedSub && translatedSub.trim()) ? translatedSub.trim()
            : (translatedCat || '');

      html += `${idx + 1}. **${formattedDate}**: ${escapeHtml(displayTitle)} — **${formatCurrency(t.amount)}**<br>`;
    });
  }

  return html;
}

function predictCategoryFromHistory(noteText) {
  const cleanNote = normalizeGreekString(noteText);
  if (!cleanNote) return null;

  const trans = state.transactions || [];
  const categoryCounts = {};

  trans.forEach(t => {
    if (t.type !== 'expense') return;
    const cNote = normalizeGreekString(t.note || '');
    const cDesc = normalizeGreekString(t.description || '');
    if ((cNote && cleanNote.includes(cNote)) || (cDesc && cleanNote.includes(cDesc)) || (cNote && cNote.includes(cleanNote)) || (cDesc && cDesc.includes(cleanNote))) {
      if ((cNote && cNote.length > 2) || (cDesc && cDesc.length > 2) || cleanNote.length > 2) {
        categoryCounts[t.category] = (categoryCounts[t.category] || 0) + 1;
      }
    }
  });

  const sorted = Object.keys(categoryCounts).sort((a, b) => categoryCounts[b] - categoryCounts[a]);
  return sorted.length > 0 ? sorted[0] : null;
}

function getSubcategoriesForCategory(category) {
  if (!category) return [];
  const rawClean = stripLeadingEmoji(category).trim();
  const cleanedCat = rawClean.toUpperCase();
  const normCat = (typeof normalizeGreekString === 'function') ? normalizeGreekString(rawClean) : cleanedCat.toLowerCase();
  const dispCat = (typeof getCategoryDisplayName === 'function') ? getCategoryDisplayName(category).toUpperCase().trim() : '';
  const normDisp = (typeof normalizeGreekString === 'function' && dispCat) ? normalizeGreekString(dispCat) : '';
  const uniqueSubcats = new Set();

  const cat = (state.categories || []).find(c => {
    if (!c) return false;
    const cClean = stripLeadingEmoji(c.name || '').trim().toUpperCase();
    const cNorm = (typeof normalizeGreekString === 'function') ? normalizeGreekString(c.name || '') : cClean.toLowerCase();
    return cClean === cleanedCat || cClean === dispCat || cNorm === normCat || (normDisp && cNorm === normDisp);
  });

  const deletedSubs = new Set(
    ((cat && Array.isArray(cat.deleted_subcategories)) ? cat.deleted_subcategories : [])
      .map(s => String(s || '').trim().toLowerCase())
  );

  // 1. Match DEFAULT_SUBCATEGORIES_MAP case-insensitively & accent-insensitively
  if (typeof DEFAULT_SUBCATEGORIES_MAP === 'object' && DEFAULT_SUBCATEGORIES_MAP) {
    Object.keys(DEFAULT_SUBCATEGORIES_MAP).forEach(key => {
      const keyClean = stripLeadingEmoji(key).trim().toUpperCase();
      const keyNorm = (typeof normalizeGreekString === 'function') ? normalizeGreekString(key) : keyClean.toLowerCase();

      if (keyClean === cleanedCat || keyClean === dispCat || keyNorm === normCat || (normDisp && keyNorm === normDisp)) {
        (DEFAULT_SUBCATEGORIES_MAP[key] || []).forEach(sub => {
          const s = String(sub || '').trim();
          if (s && !deletedSubs.has(s.toLowerCase())) uniqueSubcats.add(s);
        });
      }
    });
  }

  // 2. Match custom subcategories attached to state.categories
  if (cat && Array.isArray(cat.subcategories)) {
    cat.subcategories.forEach(sub => {
      const s = typeof sub === 'string' ? sub.trim() : (sub && sub.name ? String(sub.name).trim() : String(sub || '').trim());
      if (s && !deletedSubs.has(s.toLowerCase())) uniqueSubcats.add(s);
    });
  }

  // 3. Match subcategories from existing transactions
  (state.transactions || []).forEach(t => {
    if (t && t.category && stripLeadingEmoji(t.category).trim().toUpperCase() === cleanedCat) {
      if (t.subcategory && t.subcategory.trim() !== '') {
        const s = t.subcategory.trim();
        if (!deletedSubs.has(s.toLowerCase())) uniqueSubcats.add(s);
      }
    }
  });

  return Array.from(uniqueSubcats).sort();
}

function predictSubcategoryFromHistory(category, noteText) {
  const cleanNote = normalizeGreekString(noteText);
  if (!cleanNote || !category) return '';

  const trans = state.transactions || [];
  const subcatCounts = {};

  trans.forEach(t => {
    if (t.type !== 'expense' || t.category !== category) return;
    const cNote = normalizeGreekString(t.note || '');
    const cDesc = normalizeGreekString(t.description || '');
    if ((cNote && cleanNote.includes(cNote)) || (cDesc && cleanNote.includes(cDesc)) || (cNote && cNote.includes(cleanNote)) || (cDesc && cDesc.includes(cleanNote))) {
      if (t.subcategory && t.subcategory.trim() !== '') {
        subcatCounts[t.subcategory] = (subcatCounts[t.subcategory] || 0) + 1;
      }
    }
  });

  const sorted = Object.keys(subcatCounts).sort((a, b) => subcatCounts[b] - subcatCounts[a]);
  if (sorted.length > 0) return sorted[0];

  // Try matching subcategory names by keyword
  const subcats = getSubcategoriesForCategory(category);
  for (const sub of subcats) {
    const cleanSub = normalizeGreekString(sub);
    if (cleanNote.includes(cleanSub) || cleanSub.includes(cleanNote)) {
      return sub;
    }
  }

  // Custom heuristics
  const cleanedCat = stripLeadingEmoji(category).toUpperCase();
  if (cleanedCat === 'ΔΙΑΤΡΟΦΗ') {
    if (cleanNote.includes('φουρν') || cleanNote.includes('ψωμ') || cleanNote.includes('bakery')) {
      const match = subcats.find(s => normalizeGreekString(s).includes('φουρν') || normalizeGreekString(s).includes('ψωμ'));
      if (match) return match;
    }
    if (cleanNote.includes('σουπερ') || cleanNote.includes('super') || cleanNote.includes('σκλαβενιτ') || cleanNote.includes('lidl') || cleanNote.includes('βασιλοπ')) {
      const match = subcats.find(s => normalizeGreekString(s).includes('σουπερ') || normalizeGreekString(s).includes('super'));
      if (match) return match;
    }
  }

  return '';
}

window.updateCoachSubcategories = function (catSelectId, subcatSelectId, defaultSubcat = '') {
  const catSelect = document.getElementById(catSelectId);
  const subcatSelect = document.getElementById(subcatSelectId);
  if (!catSelect || !subcatSelect) return;

  const selectedCategory = catSelect.value;
  subcatSelect.innerHTML = '';

  const noneText = state.lang === 'el' ? 'Χωρίς υποκατηγορία' : 'No subcategory';
  const noneOpt = document.createElement('option');
  noneOpt.value = '';
  noneOpt.textContent = noneText;
  subcatSelect.appendChild(noneOpt);

  const subcategories = getSubcategoriesForCategory(selectedCategory);
  subcategories.forEach(sub => {
    const opt = document.createElement('option');
    opt.value = sub;
    opt.textContent = getSubcategoryDisplayName(sub, selectedCategory);
    if (sub === defaultSubcat) {
      opt.selected = true;
    }
    subcatSelect.appendChild(opt);
  });
};

function runCoachTransactionEntry(amount, noteText, type = 'expense', category = null, subcategory = null, accountFrom = null, dateStr = null, id = null) {
  if (isNaN(amount) || amount <= 0) {
    return state.lang === 'el' ? "🤖 Παρακαλώ δώσε ένα έγκυρο ποσό (π.χ. 'βάλε 40 για ρεύμα')." : "🤖 Please provide a valid amount (e.g., 'add 40 for electric bill').";
  }

  let predictedCat = category || predictCategoryFromHistory(noteText);

  if (!predictedCat) {
    const cleanNote = normalizeGreekString(noteText);
    if (cleanNote.includes('βενζινη') || cleanNote.includes('αμαξι') || cleanNote.includes('διοδια') || cleanNote.includes('παρκινγκ')) predictedCat = '🚗 ΑΥΤΟΚΙΝΗΤΟ';
    else if (cleanNote.includes('σουπερ') || cleanNote.includes('super') || cleanNote.includes('καφε') || cleanNote.includes('φαγητο') || cleanNote.includes('delivery') || cleanNote.includes('ντελιβερι') || cleanNote.includes('εστιατοριο') || cleanNote.includes('ταβερνα') || cleanNote.includes('φουρν') || cleanNote.includes('αρτοποι')) predictedCat = '🛒 ΔΙΑΤΡΟΦΗ';
    else if (cleanNote.includes('ρευμα') || cleanNote.includes('δεη') || cleanNote.includes('νερο') || cleanNote.includes('τηλεφωνο') || cleanNote.includes('κοινοχρηστα') || cleanNote.includes('ενοικιο')) predictedCat = '🏡 ΣΠΙΤΙ';
    else if (cleanNote.includes('γιατρο') || cleanNote.includes('φαρμακειο') || cleanNote.includes('υγεία') || cleanNote.includes('εξετασεις')) predictedCat = '❤️ ΥΓΕΙΑ';
    else if (cleanNote.includes('ποτο') || cleanNote.includes('μπυρες') || cleanNote.includes('σινεμα') || cleanNote.includes('εξοδος')) predictedCat = '🎉ΔΙΑΣΚΕΔΑΣΗ/ΕΞΟΔΟΙ';
    else if (cleanNote.includes('κομμωτηριο') || cleanNote.includes('κουρειο') || cleanNote.includes('νυχια')) predictedCat = '👕 ΠΡΟΣΩΠΙΚΗ ΦΡΟΝΤΙΔΑ';
    else if (cleanNote.includes('γυμναστηριο')) predictedCat = '🏋️ΓΥΜΝΑΣΤΗΡΙΟ';
  }

  const expenseCats = (state.categories || []).filter(c => c.type === 'expense');
  if (expenseCats.length === 0) expenseCats.push({ name: '🧩ΔΙΑΦΟΡΑ ΕΞΟΔΑ' });

  if (predictedCat && !expenseCats.some(c => c.name === predictedCat)) {
    predictedCat = null;
  }

  if (!predictedCat) {
    predictedCat = expenseCats[0].name;
  }

  const predictedSub = subcategory !== null ? subcategory : predictSubcategoryFromHistory(predictedCat, noteText);

  // Find accounts options
  let accOptionsHtml = '';
  let defaultAccount = 'Card';
  if (state.accounts && state.accounts.length > 0) {
    const cardAcc = state.accounts.find(acc => acc.type === 'card' || acc.name.toLowerCase().trim() === 'card' || acc.name.trim() === 'Κάρτα');
    const cashAcc = state.accounts.find(acc => acc.type === 'cash' || acc.name.toLowerCase().trim() === 'cash' || acc.name.trim() === 'Μετρητά');
    const defaultAcc = cardAcc || cashAcc || state.accounts[0];
    defaultAccount = accountFrom || defaultAcc.name;

    state.accounts.forEach(acc => {
      const selected = acc.name === defaultAccount ? 'selected' : '';
      accOptionsHtml += `<option value="${acc.name}" ${selected}>${acc.name}</option>`;
    });
  } else {
    accOptionsHtml = `<option value="Card" selected>${state.lang === 'el' ? 'Κάρτα' : 'Card'}</option>
                      <option value="Cash">${state.lang === 'el' ? 'Μετρητά' : 'Cash'}</option>`;
  }

  // Calculate local datetime string for input defaultValue
  let defaultDateTime;
  if (dateStr) {
    const d = new Date(dateStr);
    const tzOffset = d.getTimezoneOffset() * 60000;
    defaultDateTime = new Date(d.getTime() - tzOffset).toISOString().slice(0, 16);
  } else {
    const now = new Date();
    const tzOffset = now.getTimezoneOffset() * 60000;
    defaultDateTime = new Date(now.getTime() - tzOffset).toISOString().slice(0, 16);
  }

  const seed = Math.floor(Math.random() * 1000000);
  const amtInputId = 'coach-tx-amt-input-' + seed;
  const noteInputId = 'coach-tx-note-input-' + seed;
  const dateInputId = 'coach-tx-date-input-' + seed;
  const catSelectId = 'coach-tx-cat-select-' + seed;
  const subcatSelectId = 'coach-tx-subcat-select-' + seed;
  const accSelectId = 'coach-tx-acc-select-' + seed;
  const btnId = 'coach-tx-btn-' + seed;

  let catOptionsHtml = '';
  expenseCats.forEach(c => {
    const selected = c.name === predictedCat ? 'selected' : '';
    catOptionsHtml += `<option value="${c.name}" ${selected}>${getCategoryDisplayName(c.name)}</option>`;
  });

  const subcategories = getSubcategoriesForCategory(predictedCat);
  let subOptionsHtml = `<option value="">${state.lang === 'el' ? 'Χωρίς υποκατηγορία' : 'No subcategory'}</option>`;
  subcategories.forEach(sub => {
    const selected = sub === predictedSub ? 'selected' : '';
    subOptionsHtml += `<option value="${sub}" ${selected}>${getSubcategoryDisplayName(sub, predictedCat)}</option>`;
  });

  const isEl = state.lang === 'el';
  const badgeTitle = id
    ? (isEl ? 'Επεξεργασία Συναλλαγής' : 'Edit Transaction')
    : (isEl ? 'Προτεινόμενη Καταχώρηση' : 'Suggested Transaction');
  const btnLabel = id
    ? (isEl ? 'Αποθήκευση Αλλαγών' : 'Save Changes')
    : (isEl ? 'Καταχώρηση Συναλλαγής' : 'Confirm Transaction');

  let html = `
    <div class="ai-tx-luxury-card">
      <div class="ai-tx-top-badge">
        <span style="display: flex; align-items: center; gap: 6px;">
          <i class="fa-solid fa-bolt" style="color: #818cf8;"></i>
          ${badgeTitle}
        </span>
        <span style="font-size: 10px; color: var(--text-muted); font-weight: 500;">
          ${dateStr ? String(dateStr).split('T')[0] : (isEl ? 'Σήμερα' : 'Today')}
        </span>
      </div>

      <!-- Hero Amount & Note Row -->
      <div class="ai-tx-hero-row">
        <div style="flex: 1; min-width: 0; padding-right: 12px;">
          <div style="font-size: 10px; font-weight: 600; text-transform: uppercase; color: var(--text-muted); margin-bottom: 3px;">
            ${isEl ? 'Περιγραφή' : 'Description'}
          </div>
          <input type="text" id="${noteInputId}" value="${noteText.replace(/"/g, '&quot;')}" 
            style="width: 100%; background: transparent; border: none; border-bottom: 1px dashed rgba(255,255,255,0.2); color: #fff; font-size: 15px; font-weight: 700; outline: none; padding: 2px 0;">
        </div>
        <div style="text-align: right; flex-shrink: 0;">
          <div style="font-size: 10px; font-weight: 600; text-transform: uppercase; color: var(--text-muted); margin-bottom: 3px;">
            ${isEl ? 'Ποσό' : 'Amount'}
          </div>
          <div style="display: flex; align-items: center; justify-content: flex-end; gap: 2px;">
            <span style="font-family: 'Outfit', sans-serif; font-size: 18px; font-weight: 800; color: ${type === 'income' ? '#34d399' : '#f87171'};">${type === 'income' ? '+€' : '-€'}</span>
            <input type="number" step="0.01" id="${amtInputId}" value="${amount.toFixed(2)}"
              style="width: 85px; background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; color: #fff; font-family: 'Outfit', sans-serif; font-size: 18px; font-weight: 800; text-align: right; padding: 2px 6px; outline: none;">
          </div>
        </div>
      </div>

      <!-- Metadata Dropdowns Grid -->
      <div class="ai-tx-meta-grid">
        <div class="ai-tx-meta-pill">
          <i class="fa-solid fa-shapes" style="color: #818cf8; font-size: 13px; flex-shrink: 0;"></i>
          <div style="flex: 1; min-width: 0;">
            <div class="ai-tx-meta-label">${isEl ? 'Κατηγορία' : 'Category'}</div>
            <select id="${catSelectId}" onchange="window.updateCoachSubcategories('${catSelectId}', '${subcatSelectId}')"
              style="width: 100%; background: transparent; border: none; color: #fff; font-size: 11.5px; font-weight: 700; outline: none; cursor: pointer; padding: 0;">
              ${catOptionsHtml}
            </select>
          </div>
        </div>

        <div class="ai-tx-meta-pill">
          <i class="fa-solid fa-credit-card" style="color: #38bdf8; font-size: 13px; flex-shrink: 0;"></i>
          <div style="flex: 1; min-width: 0;">
            <div class="ai-tx-meta-label">${isEl ? 'Πληρωμή' : 'Account'}</div>
            <select id="${accSelectId}"
              style="width: 100%; background: transparent; border: none; color: #fff; font-size: 11.5px; font-weight: 700; outline: none; cursor: pointer; padding: 0;">
              ${accOptionsHtml}
            </select>
          </div>
        </div>
      </div>

      <!-- Subcategory & Date (Secondary Row) -->
      <div class="ai-tx-meta-grid">
        <div class="ai-tx-meta-pill">
          <i class="fa-solid fa-tag" style="color: #c084fc; font-size: 12px; flex-shrink: 0;"></i>
          <div style="flex: 1; min-width: 0;">
            <div class="ai-tx-meta-label">${isEl ? 'Υποκατηγορία' : 'Subcategory'}</div>
            <select id="${subcatSelectId}"
              style="width: 100%; background: transparent; border: none; color: #fff; font-size: 11px; font-weight: 600; outline: none; cursor: pointer; padding: 0;">
              ${subOptionsHtml}
            </select>
          </div>
        </div>

        <div class="ai-tx-meta-pill">
          <i class="fa-regular fa-clock" style="color: #94a3b8; font-size: 12px; flex-shrink: 0;"></i>
          <div style="flex: 1; min-width: 0;">
            <div class="ai-tx-meta-label">${isEl ? 'Ημερομηνία' : 'Date'}</div>
            <input type="datetime-local" id="${dateInputId}" value="${defaultDateTime}"
              style="width: 100%; background: transparent; border: none; color: #fff; font-size: 11px; font-weight: 600; outline: none; padding: 0;">
          </div>
        </div>
      </div>

      <!-- Luxury Confirm Action Button -->
      <button id="${btnId}" class="ai-tx-save-btn" onclick="window.submitCoachTransaction(document.getElementById('${amtInputId}').value, '${type}', document.getElementById('${catSelectId}').value, document.getElementById('${subcatSelectId}').value, document.getElementById('${accSelectId}').value, document.getElementById('${noteInputId}').value, document.getElementById('${dateInputId}').value, this.id, '${id || ''}')">
        <i class="fa-solid fa-check"></i>
        <span>${btnLabel}</span>
      </button>
    </div>
  `;
  return html;
}

function runCoachTopCategories() {
  const today = new Date();
  const currYear = today.getFullYear();
  const currMonth = today.getMonth();
  const trans = state.transactions || [];
  const totals = {};

  trans.forEach(t => {
    if (t.type !== 'expense' || !t.date) return;
    const parts = String(t.date).split('T')[0].split(' ')[0].split('-');
    if (parts.length !== 3) return;
    if (parseInt(parts[0], 10) === currYear && (parseInt(parts[1], 10) - 1) === currMonth) {
      totals[t.category] = (totals[t.category] || 0) + CurrencyService.toBase(t);
    }
  });

  const sorted = Object.keys(totals).map(cat => ({ cat, amt: totals[cat] })).sort((a, b) => b.amt - a.amt);
  if (sorted.length === 0) {
    return state.lang === 'el' ? "📊 Δεν βρέθηκαν έξοδα για αυτόν τον μήνα." : "📊 No expenses found for this month.";
  }

  let html = state.lang === 'el' ? "📊 **Οι κατηγορίες με τα περισσότερα έξοδα αυτόν τον μήνα:**<br><br>" : "📊 **Your top spending categories this month:**<br><br>";
  sorted.slice(0, 3).forEach((item, idx) => {
    html += `${idx + 1}. **${getCategoryDisplayName(item.cat)}**: **${formatCurrency(item.amt)}**<br>`;
  });
  return html;
}

function runCoachWhatIfSimulation(amount, itemName = null) {
  const pacing = getCoachAveragePacing();
  const startBalance = pacing.totalBalance;
  const monthlySavings = pacing.avgSavings;

  if (isNaN(amount) || amount <= 0) {
    return state.lang === 'el' ? "Παρακαλώ δώσε ένα έγκυρο ποσό για την προσομοίωση." : "Please provide a valid amount for the simulation.";
  }

  const nameStr = itemName ? `**${itemName}**` : (state.lang === 'el' ? "αυτή την αγορά" : "this purchase");
  const remainingBalance = startBalance - amount;

  let html = "";
  if (state.lang === 'el') {
    html += `🔮 **Προσομοίωση Αγοράς (What-If): ${formatCurrency(amount)}**<br><br>`;
    html += `Αν προχωρήσεις στην αγορά για ${nameStr} αξίας **${formatCurrency(amount)}**:<br><br>`;
    html += `• Το τρέχον υπόλοιπό σου θα μειωθεί από **${formatCurrency(startBalance)}** σε **${formatCurrency(remainingBalance)}**.<br>`;

    if (remainingBalance < 0) {
      html += `🔴 **Προσοχή!** Το υπόλοιπό σου θα γίνει αρνητικό (**${formatCurrency(remainingBalance)}**). Αυτή η αγορά ξεπερνά τις οικονομικές σου δυνατότητες αυτή τη στιγμή.<br>`;
    } else {
      html += `🟢 Διατηρείς θετικό υπόλοιπο ασφαλείας (**${formatCurrency(remainingBalance)}**).<br>`;
    }

    if (monthlySavings > 0) {
      const monthsDelay = Math.ceil(amount / monthlySavings);
      html += `• Θα χρειαστείς **${monthsDelay} μήνες** αποταμίευσης για να αναπληρώσεις αυτό το ποσό.<br>`;

      const targetAmount = 50000;
      if (startBalance < targetAmount) {
        const originalMonths = Math.ceil((targetAmount - startBalance) / monthlySavings);
        const newMonths = Math.ceil((targetAmount - remainingBalance) / monthlySavings);
        html += `• Η επίτευξη του στόχου των ${formatCurrency(targetAmount)} θα καθυστερήσει κατά **${newMonths - originalMonths} μήνες**.<br>`;
      }
    }
  } else {
    html += `🔮 **What-If Purchase Simulation: ${formatCurrency(amount)}**<br><br>`;
    html += `If you purchase ${nameStr} for **${formatCurrency(amount)}**:<br><br>`;
    html += `• Your balance will decrease from **${formatCurrency(startBalance)}** to **${formatCurrency(remainingBalance)}**.<br>`;

    if (remainingBalance < 0) {
      html += `🔴 **Warning!** Your balance will drop to negative (**${formatCurrency(remainingBalance)}**). This purchase is beyond your current financial limit.<br>`;
    } else {
      html += `🟢 You maintain a positive buffer of **${formatCurrency(remainingBalance)}**.<br>`;
    }

    if (monthlySavings > 0) {
      const monthsDelay = Math.ceil(amount / monthlySavings);
      html += `• It will take you **${monthsDelay} months** of savings to recover this amount.<br>`;

      const targetAmount = 50000;
      if (startBalance < targetAmount) {
        const originalMonths = Math.ceil((targetAmount - startBalance) / monthlySavings);
        const newMonths = Math.ceil((targetAmount - remainingBalance) / monthlySavings);
        html += `• Reaching your ${formatCurrency(targetAmount)} goal will be delayed by **${newMonths - originalMonths} months**.<br>`;
      }
    }
  }
  return html;
}

function runCoachSearchQuery(keyword) {
  const cleanKeyword = normalizeGreekString(keyword);
  const trans = state.transactions || [];
  const today = new Date();
  const currentYear = today.getFullYear();

  const matchedTrans = trans.filter(t => {
    if (!t.date || isTransferTransaction(t)) return false;

    const datePart = String(t.date).split('T')[0];
    const parts = datePart.split('-');
    if (parts.length !== 3) return false;
    const y = parseInt(parts[0], 10);
    if (y !== currentYear) return false;

    const cleanCat = normalizeGreekString(t.category);
    const cleanSub = normalizeGreekString(t.subcategory || '');
    const cleanNote = normalizeGreekString(t.note || '');
    const cleanDesc = normalizeGreekString(t.description || '');

    return cleanCat.includes(cleanKeyword) ||
      cleanSub.includes(cleanKeyword) ||
      cleanNote.includes(cleanKeyword) ||
      cleanDesc.includes(cleanKeyword);
  });

  if (matchedTrans.length === 0) {
    return state.lang === 'el'
      ? `Δεν βρήκα καμία συναλλαγή φέτος με τον όρο **"${keyword}"**.`
      : `No transactions found this year with the term **"${keyword}"**.`;
  }

  const totalAmt = matchedTrans.reduce((sum, t) => sum + CurrencyService.toBase(t), 0);
  const count = matchedTrans.length;
  const avg = totalAmt / count;

  let html = "";
  if (state.lang === 'el') {
    html += `🔍 **Αποτελέσματα Αναζήτησης για: "${keyword}"**<br><br>`;
    html += `• Βρέθηκαν **${count} συναλλαγές** φέτος.<br>`;
    html += `• Συνολικό ποσό: **${formatCurrency(totalAmt)}**<br>`;
    html += `• Μέσος όρος ανά συναλλαγή: **${formatCurrency(avg)}**<br><br>`;
    html += `💡 *Συμβουλή: Προσπαθήστε να κρατάτε σημειώσεις (notes) σε κάθε συναλλαγή για να μπορείτε να τις αναζητάτε ακόμα πιο εύκολα!*`;
  } else {
    html += `🔍 **Search Results for: "${keyword}"**<br><br>`;
    html += `• Found **${count} transactions** this year.<br>`;
    html += `• Total amount: **${formatCurrency(totalAmt)}**<br>`;
    html += `• Average per transaction: **${formatCurrency(avg)}**<br><br>`;
    html += `💡 *Tip: Try adding notes to your transactions to search for specific items even easier!*`;
  }
  return html;
}

function processCoachQuery(queryText) {
  const normQuery = normalizeGreekString(queryText);
  const cleanQuery = queryText.toLowerCase().trim();

  if (cleanQuery === 'overspending' || normQuery.includes('υπερβολικα')) {
    return runCoachOverspendingAnalysis();
  }
  if (cleanQuery === 'savings' || normQuery.includes('αποταμιευσω')) {
    return runCoachSavingsAdvice();
  }
  if (cleanQuery === 'forecast_5y' || normQuery.includes('5 χρονια') || normQuery.includes('5 ετη')) {
    return runCoachFiveYearForecast();
  }
  if (cleanQuery === 'milestone_50k' || cleanQuery === 'milestone_50000') {
    return runCoachTargetMilestone(50000);
  }
  if (cleanQuery.startsWith('milestone_')) {
    let amtStr = cleanQuery.replace('milestone_', '');
    const amt = amtStr.endsWith('k') ? (parseFloat(amtStr) * 1000) : (parseInt(amtStr, 10) || 50000);
    return runCoachTargetMilestone(amt);
  }

  const localizedAmt = typeof parseLocalizedAmount === 'function'
    ? parseLocalizedAmount(queryText)
    : (typeof window.parseLocalizedAmount === 'function' ? window.parseLocalizedAmount(queryText) : null);

  // 0. Action commands (add transaction)
  const isAddCommand = normQuery.includes('βαλε') || normQuery.includes('προσθεσε') || normQuery.includes('καταχωρησε') || normQuery.includes('χρεωσε') || normQuery.includes('ξοδεψα') || normQuery.includes('εδωσα') || normQuery.includes('πληρωσα') || normQuery.includes('χάλασα') || normQuery.includes('xalasa') || normQuery.includes('χάλασαμε') || normQuery.includes('xalasame') || normQuery.includes('add') || normQuery.includes('spent');
  if (isAddCommand && localizedAmt && localizedAmt > 0) {
    const amount = localizedAmt;
    let noteText = queryText.replace(/\d+(?:[.,]\d+)?/g, '').replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?¿€]/g, '').trim();
    const stopWords = ['βαλε', 'προσθεσε', 'καταχωρησε', 'χρεωσε', 'ξοδεψα', 'εδωσα', 'πληρωσα', 'χάλασα', 'xalasa', 'χάλασαμε', 'xalasame', 'ευρω', 'ευρω', 'euro', 'σε', 'στο', 'στην', 'στα', 'στον', 'για', 'απο', 'ενα', 'μια', 'add', 'spent', 'paid', 'for', 'on', 'euros'];
    const words = noteText.split(/\s+/).filter(w => w.length > 1 && !stopWords.includes(normalizeGreekString(w)));
    const cleanNote = words.join(' ') || '';

    // Distinguish between sum search "ποσα ξοδεψα" and action "ξοδεψα 40"
    if (!normQuery.includes('ποσα') && !normQuery.includes('ποσο') && !normQuery.includes('how much') && !normQuery.includes('τι ')) {
      return runCoachTransactionEntry(amount, cleanNote);
    }
  }

  // 1. Discuss Category Increase
  if (normQuery.includes('γιατι αυξηθηκαν') || normQuery.includes('why did my') || normQuery.includes('αυξηθηκαν') || normQuery.includes('did my') || normQuery.includes('αυξηση')) {
    let catName = "";
    const grMatch = queryText.match(/οι\s+([α-ωΑ-ΩάέήίόύώΆΈΉΊΌΎΏϊϋΐΰa-zA-Z\s]+?)\s+μου/i);
    const enMatch = queryText.match(/my\s+([a-zA-Z\s]+?)\s+rose/i) || queryText.match(/did\s+([a-zA-Z\s]+?)\s+increase/i);

    if (grMatch && grMatch[1]) catName = grMatch[1].trim();
    else if (enMatch && enMatch[1]) catName = enMatch[1].trim();
    else {
      const words = normQuery.split(/\s+/);
      const stopWords = ['γιατι', 'αυξηθηκαν', 'οι', 'μου', 'αυτον', 'τον', 'μηνα', 'why', 'did', 'my', 'increase', 'this', 'month', 'expense', 'expenses', 'αυξηση', 'εξοδα', 'εξοδων'];
      const possibleCats = words.filter(w => w.length > 2 && !stopWords.includes(w));
      if (possibleCats.length > 0) catName = possibleCats[0];
    }

    if (catName) {
      return runCoachCategoryAnalysis(catName);
    }
  }

  // 2. What-If Simulator
  const isSimulation = normQuery.includes('αγορασ') || normQuery.includes('αγορα') || normQuery.includes('παρω') || normQuery.includes('buy') || normQuery.includes('purchase');
  if (isSimulation && localizedAmt && localizedAmt > 0) {
    const amount = localizedAmt;
    let itemName = queryText.replace(/\d+(?:[.,]\d+)?/g, '').replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?¿€]/g, '').trim();
    const stopWords = ['αν', 'να', 'αγορασω', 'αγοράσω', 'παρω', 'πάρω', 'αγορα', 'αγορά', 'για', 'ευρω', 'ευρώ', 'euro', 'buy', 'purchase', 'a', 'an', 'the', 'what', 'if', 'i'];
    const words = itemName.split(/\s+/).filter(w => w.length > 2 && !stopWords.includes(normalizeGreekString(w)));
    const cleanItemName = words.join(' ') || null;
    return runCoachWhatIfSimulation(amount, cleanItemName);
  }

  // 3. Milestone Target
  if (normQuery.includes('φτασω') || normQuery.includes('reach') || normQuery.includes('αποκτησω') || normQuery.includes('στοχο') || normQuery.includes('target') || normQuery.includes('μαζεψω') || normQuery.includes('εχω') || normQuery.includes('στην ακρη')) {
    if (localizedAmt && localizedAmt > 0) {
      return runCoachTargetMilestone(localizedAmt);
    }
  }

  // 4. Budgets Status
  if (normQuery.includes('προϋπολογισμ') || normQuery.includes('προϋπολογισμο') || normQuery.includes('προϋπολογισμοι') || normQuery.includes('προϋπολογισμους') || normQuery.includes('proypologism') || normQuery.includes('budget') || normQuery.includes('οριο') || normQuery.includes('ορια')) {
    const budgets = state.budgets || [];
    const activeExpenses = state.transactions.filter(t => {
      const datePart = String(t.date || '').split('T')[0];
      const parts = datePart.split('-');
      if (parts.length !== 3) return false;
      const y = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10) - 1;
      const today = new Date();
      return t.type === 'expense' && y === today.getFullYear() && m === today.getMonth();
    });

    const expenseTotals = {};
    activeExpenses.forEach(t => {
      expenseTotals[t.category] = (expenseTotals[t.category] || 0) + CurrencyService.toBase(t);
    });

    let html = state.lang === 'el' ? "📊 **Κατάσταση Προϋπολογισμών (Budgets):**<br><br>" : "📊 **Budget Status:**<br><br>";
    let hasBudgets = false;

    budgets.forEach(b => {
      if (b.is_deleted) return;
      const catInfo = getCategoryInfo(b.category, 'expense');
      const catName = catInfo.name || b.category;
      const limit = parseFloat(b.amount) || 0;
      if (limit > 0) {
        hasBudgets = true;
        const spent = expenseTotals[catName] || 0;
        const pct = Math.round((spent / limit) * 100);
        const dispCat = getCategoryDisplayName(catName);
        const indicator = pct >= 100 ? '🔴' : pct >= 80 ? '🟡' : '🟢';
        html += `${indicator} **${dispCat}**: ${formatCurrency(spent)} / ${formatCurrency(limit)} (**${pct}%**)<br>`;
      }
    });

    if (!hasBudgets) {
      return state.lang === 'el'
        ? "📊 Δεν έχεις ορίσει προϋπολογισμούς ακόμα. Μπορείς να ορίσεις Budgets πηγαίνοντας στα **Περισσότερα -> Όρια Κατηγοριών**."
        : "📊 You haven't set any budgets yet. You can set them in **More -> Category Limits**.";
    }
    return html;
  }

  // 5. Top categories breakdown
  if (normQuery.includes('που ξοδευω τα περισσοτερα') || normQuery.includes('που ξοδευω τα') || normQuery.includes('που πανε τα λεφτα') || normQuery.includes('μεγαλυτερα εξοδα') || normQuery.includes('where do i spend') || normQuery.includes('top spending')) {
    return runCoachTopCategories();
  }

  // 6. Conversational Sum Search (e.g. "πόσα ξόδεψα σε καφέ", "πόσα λεφτά έχω χαλάσει στο κομμωτήριο φέτος")
  const isSpendingQuery = normQuery.includes('ποσα') || normQuery.includes('ποσο') || normQuery.includes('how much') || normQuery.includes('how many') || normQuery.includes('spent') || normQuery.includes('xodepsa') || normQuery.includes('xodepsame') || normQuery.includes('xalasa') || normQuery.includes('xalasame');
  if (isSpendingQuery) {
    let keyword = "";
    const grMatch = queryText.match(/(?:σε|για|στο|στη|στην|στα|στον|στους|στις)\s+([α-ωΑ-ΩάέήίόύώΆΈΉΊΌΎΏϊϋΐΰa-zA-Z\s]+)/i);
    const enMatch = queryText.match(/(?:on|for|at|in)\s+([a-zA-Z\s]+)/i);

    if (grMatch && grMatch[1]) {
      keyword = grMatch[1].trim();
    } else if (enMatch && enMatch[1]) {
      keyword = enMatch[1].trim();
    } else {
      const stopWords = [
        'ποσα', 'ποσο', 'ποσα λεφτα', 'ποσο λεφτα', 'λεφτα', 'χρηματα', 'εχω', 'εχουμε', 'χαλασει', 'χαλασα',
        'χαλασαμε', 'ξοδεψει', 'ξοδεψα', 'ξοδεψαμε', 'εδωσα', 'εδωσαμε', 'δωσει', 'πληρωσα', 'πληρωσαμε',
        'πληρωσει', 'φετος', 'μηνα', 'ετος', 'σημερα', 'χθες', 'how', 'much', 'did', 'i', 'spend', 'spent',
        'on', 'for', 'this', 'year', 'month', 'today', 'yesterday'
      ];
      const words = normQuery.split(/\s+/).filter(w => w.length > 2 && !stopWords.includes(w));
      if (words.length > 0) {
        keyword = words[0];
      }
    }

    if (keyword) {
      keyword = keyword.replace(/(?:φετος|φέτος|αυτον|τον|μηνα|μήνα|αυτο|το|ετος|έτος|this year|this month|year|month)/gi, '').trim();
      if (keyword) {
        return runCoachSearchQuery(keyword);
      }
    }
  }

  // 7. General search fallback
  const cleanKeyword = cleanQuery.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "").trim();
  if (cleanKeyword.length >= 2) {
    return runCoachSearchQuery(cleanKeyword);
  }

  return state.lang === 'el'
    ? `🤖 **Δεν μπόρεσα να κατανοήσω πλήρως την ερώτηση.**<br><br>Μπορείς να δοκιμάσεις κάποια από τις έτοιμες προτάσεις από κάτω, ή να ρωτήσεις για μια συγκεκριμένη κατηγορία/λέξη (π.χ. «καφέ», «φαγητό», «βενζίνη», «υπερβολικά», «αποταμίευση»).`
    : `🤖 **I couldn't quite understand the question.**<br><br>You can try using one of the suggestion chips below, or ask about a specific category or search term (e.g., 'coffee', 'food', 'petrol', 'overspending', 'savings').`;
}

window.submitCoachTransaction = async function (amount, type, category, subcategory, accountFrom, note, dateString, btnId, id = null) {
  const btn = document.getElementById(btnId);
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = state.lang === 'el' ? '⏳ Καταχώρηση...' : '⏳ Saving...';
  }

  const parsedAmount = parseFloat(amount);
  if (isNaN(parsedAmount) || parsedAmount <= 0) {
    window.showAlert(state.lang === 'el' ? 'Παρακαλώ δώστε ένα έγκυρο ποσό.' : 'Please enter a valid amount.');
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = state.lang === 'el' ? '✅ Καταχώρηση' : '✅ Register';
    }
    return;
  }

  const txId = id || generateUUID();
  const transaction = {
    id: txId,
    type: type || 'expense',
    amount: parsedAmount,
    category: category || '🧩ΔΙΑΦΟΡΑ ΕΞΟΔΑ',
    subcategory: subcategory || '',
    account_from: accountFrom || 'Card',
    account_to: null,
    note: note || '',
    date: dateString ? new Date(dateString).toISOString() : new Date().toISOString(),
    user_id: state.currentUser ? state.currentUser.id : null,
    family_id: (state.activeAccountMode !== 'personal' && state.userProfile && state.userProfile.family_id) ? state.userProfile.family_id : null
  };

  try {
    await saveTransaction(transaction);
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = state.lang === 'el' ? '✅ Καταχωρήθηκε!' : '✅ Saved!';
      btn.style.backgroundColor = 'var(--success)';
      btn.style.opacity = '0.9';
      btn.style.cursor = 'default';
    }

    // 1. Permanently update the stored chat message in localStorage & Supabase
    updateAdvisorMessageSavedState(btnId);

    // 2. Trigger cloud sync immediately so Web / other devices receive it in real-time
    if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
      syncLocalTransactionsToCloud().catch(err => console.warn('[CoachTx] Sync to cloud error:', err));
    }
  } catch (err) {
    console.error('Error saving transaction from coach:', err);
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = state.lang === 'el' ? '❌ Αποτυχία' : '❌ Failed';
      btn.style.backgroundColor = 'var(--danger)';
    }
  }
};

function openRecurringTemplatesModal() {
  const container = document.getElementById('recurring-templates-list-container');
  if (!container) return;

  if (!state.recurringTemplates || state.recurringTemplates.length === 0) {
    try {
      const cached = JSON.parse(localStorage.getItem('recurring_templates') || '[]');
      if (Array.isArray(cached) && cached.length > 0) {
        state.recurringTemplates = cached;
      }
    } catch (e) { }
  }

  container.innerHTML = '';
  const templates = state.recurringTemplates || [];
  const lang = state.lang || 'el';

  if (templates.length === 0) {
    const emptyMsg = TRANSLATIONS[lang]['no_recurring_templates'] || 'No active recurring transactions found.';
    container.innerHTML = `
      <div style="text-align: center; padding: 32px 16px; color: var(--text-secondary); font-size: 14px; line-height: 1.5;">
        ${emptyMsg}
      </div>
    `;
  } else {
    templates.forEach(t => {
      // Find category styling using robust getCategoryInfo helper
      const catInfo = getCategoryInfo(t.category, t.type);
      const icon = catInfo.icon || (t.type === 'income' ? '🟢' : '🔴');
      const color = catInfo.color || '#78909c';

      // Format preset type label
      let presetLabel = t.preset || 'custom';
      if (presetLabel === 'monthly') {
        const dayLabel = TRANSLATIONS[lang]['monthly_on_day'] || 'Monthly on day';
        const startDate = t.startDate ? new Date(t.startDate) : null;
        const dayNum = startDate ? startDate.getDate() : 1;
        presetLabel = `${dayLabel} ${dayNum}`;
      } else {
        presetLabel = TRANSLATIONS[lang]['stats_period_' + presetLabel] || presetLabel;
      }

      let endDateLabel = '';
      if (t.endDate) {
        const parts = String(t.endDate).split('T')[0].split('-');
        if (parts.length === 3) {
          const dd = parts[2];
          const mm = parts[1];
          const yyyy = parts[0];
          endDateLabel = lang === 'el' ? ` • Έως ${dd}/${mm}/${yyyy}` : ` • Until ${dd}/${mm}/${yyyy}`;
        } else {
          const endD = new Date(t.endDate);
          if (!isNaN(endD.getTime())) {
            const day = String(endD.getDate()).padStart(2, '0');
            const month = String(endD.getMonth() + 1).padStart(2, '0');
            const year = endD.getFullYear();
            endDateLabel = lang === 'el' ? ` • Έως ${day}/${month}/${year}` : ` • Until ${day}/${month}/${year}`;
          }
        }
      }

      const itemHtml = `
        <div class="recurring-template-row" style="display: flex; flex-direction: row; align-items: center; justify-content: space-between; padding: 12px 14px; border: 1px solid var(--border); border-radius: 14px; background: var(--bg-card); gap: 12px; margin-bottom: 0; min-height: 64px; box-sizing: border-box; width: 100%;">
          <div style="display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1; flex-direction: row;">
            ${(typeof renderCategoryIconHtml === 'function')
          ? renderCategoryIconHtml(t.category, { size: 'md', customColor: color, transType: t.type })
          : `<div style="width: 42px; height: 42px; border-radius: 12px; background: ${color}20; color: ${color}; display: flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0;">${icon}</div>`}
            <div style="display: flex; flex-direction: column; min-width: 0; text-align: left; flex: 1;">
              <span style="font-weight: 700; color: var(--text-primary); font-size: 14.5px; word-break: break-word; line-height: 1.3; display: flex; align-items: center; gap: 6px;">${t.note || t.category}<i class="fa-solid fa-arrows-rotate recurring-arrows-icon" style="font-size: 12px; color: var(--primary);" title="${lang === 'el' ? 'Επαναλαμβανόμενη' : 'Recurring'}"></i></span>
              <span style="font-size: 12px; color: var(--text-secondary); margin-top: 3px; word-break: break-word; line-height: 1.2;">${presetLabel} • ${getCurrencySymbol()} ${formatDisplayAmount(t.amount, t.currency || state.mainCurrency || 'EUR')}${endDateLabel}</span>
            </div>
          </div>
          <div style="display: flex; align-items: center; gap: 6px; flex-shrink: 0;">
            <button class="details-btn" onclick="openRecurringDetailsModal('${t.id}')" title="${lang === 'el' ? 'Προβολή επαναλήψεων' : 'View repetitions'}" style="width: 34px; height: 34px; border-radius: 10px; border: 1px solid var(--border); background: rgba(255,255,255,0.03); color: var(--text-secondary); display: flex; align-items: center; justify-content: center; font-size: 14px; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.backgroundColor='rgba(var(--accent-rgb), 0.15)'; this.style.color='var(--primary)';" onmouseout="this.style.backgroundColor='rgba(255,255,255,0.03)'; this.style.color='var(--text-secondary)';">
              <i class="fa-regular fa-eye"></i>
            </button>
            <button class="edit-btn" onclick="openRecurringEditModal('${t.id}')" title="${lang === 'el' ? 'Επεξεργασία επανάληψης' : 'Edit recurring'}" style="width: 34px; height: 34px; border-radius: 10px; border: 1px solid var(--border); background: rgba(255,255,255,0.03); color: var(--text-secondary); display: flex; align-items: center; justify-content: center; font-size: 14px; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.backgroundColor='rgba(var(--accent-rgb), 0.15)'; this.style.color='var(--primary)';" onmouseout="this.style.backgroundColor='rgba(255,255,255,0.03)'; this.style.color='var(--text-secondary)';">
              <i class="fa-regular fa-pen-to-square"></i>
            </button>
            <button class="delete-btn" onclick="deleteRecurringTemplate('${t.id}')" title="${lang === 'el' ? 'Διαγραφή' : 'Delete'}" style="width: 34px; height: 34px; border-radius: 10px; border: 1px solid var(--border); background: rgba(255,255,255,0.03); color: var(--danger); display: flex; align-items: center; justify-content: center; font-size: 14px; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.backgroundColor='rgba(255, 91, 91, 0.15)'; this.style.borderColor='rgba(255, 91, 91, 0.3)';" onmouseout="this.style.backgroundColor='rgba(255,255,255,0.03)'; this.style.borderColor='var(--border)';">
              <i class="fa-regular fa-trash-can"></i>
            </button>
          </div>
        </div>
      `;
      container.insertAdjacentHTML('beforeend', itemHtml);
    });
  }

  openModal('recurring-templates-modal');
}

// ============================================================
// RECURRING DETAILS: show all repetitions + edit template name
// ============================================================
let activeRecurringDetailsTemplateId = null;

function openRecurringDetailsModal(templateId) {
  const userId = state.userId;
  const partnerId = state.partnerId;
  const familyId = state.familyId;
  const template = (state.recurringTemplates || []).find(t => String(t.id) === String(templateId));
  if (!template) return;
  activeRecurringDetailsTemplateId = template.id;

  const lang = state.lang || 'el';

  // Title
  const titleEl = document.getElementById('recurring-details-title');
  if (titleEl) titleEl.textContent = lang === 'el' ? '🔁 Επαναλήψεις' : '🔁 Repetitions';

  // Name label
  const nameLabel = document.getElementById('recurring-details-name-label');
  if (nameLabel) nameLabel.textContent = lang === 'el' ? 'Όνομα Επανάληψης' : 'Recurring Name';

  // List label
  const listLabel = document.getElementById('recurring-details-list-label');
  if (listLabel) listLabel.textContent = lang === 'el' ? 'Όλες οι Επαναλήψεις' : 'All Repetitions';

  // Name input
  const nameInput = document.getElementById('recurring-details-name-input');
  if (nameInput) nameInput.value = template.note || '';

  // Save button text
  const saveBtn = document.querySelector('#recurring-details-modal .modal-body button[onclick="saveRecurringTemplateName()"]');
  if (saveBtn) {
    saveBtn.innerHTML = `<i class="fa-solid fa-floppy-disk" style="font-size: 12px; margin-right: 4px;"></i>${lang === 'el' ? 'Αποθήκευση' : 'Save'}`;
  }

  // Gather all repetitions (transactions linked to this template or belonging to its recurring series)
  const templateIdStr = String(template.id);
  const ctx = {
    templateId: template.id,
    amount: template.amount,
    type: template.type,
    category: template.category
  };
  let updatedAnyLink = false;
  const repetitions = (state.transactions || []).filter(tx => {
    // 1. Direct link by recurring_template_id
    if (String(tx.recurring_template_id || '') === templateIdStr) return true;

    // 2. Belongs to recurring series (amount + type + category + series occurrence date)
    if (typeof _txBelongsToRecurringSeries === 'function' && _txBelongsToRecurringSeries(tx, ctx)) {
      tx.recurring_template_id = template.id;
      updatedAnyLink = true;
      return true;
    }

    // 3. Robust fallback: same amount + type + (matching note or matching category) within template active timeline
    const txAmount = (parseFloat(tx.amount) || 0).toFixed(2);
    const templAmount = (parseFloat(template.amount) || 0).toFixed(2);
    if (txAmount === templAmount && tx.type === template.type) {
      const txNote = normalizeGreekString(tx.note || tx.description || '');
      const templNote = normalizeGreekString(template.note || template.description || '');
      const notesMatch = txNote.length > 0 && templNote.length > 0 && (txNote === templNote || txNote.includes(templNote) || templNote.includes(txNote));
      const catMatch = isSameCategory(tx.category, template.category);
      if (notesMatch || catMatch) {
        const txDate = String(tx.date || '').split('T')[0].split(' ')[0];
        const templateStart = template.startDate ? String(template.startDate).split('T')[0] : '2000-01-01';
        const templateEnd = template.endDate ? String(template.endDate).split('T')[0] : '2099-12-31';
        if (txDate >= templateStart && txDate <= templateEnd) {
          tx.recurring_template_id = template.id;
          updatedAnyLink = true;
          return true;
        }
      }
    }
    return false;
  });

  if (updatedAnyLink) {
    localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
  }

  // Sort by date ascending
  repetitions.sort((a, b) => {
    const da = String(a.date || '').split('T')[0];
    const db = String(b.date || '').split('T')[0];
    return da.localeCompare(db);
  });

  const listContainer = document.getElementById('recurring-details-list-container');
  if (!listContainer) return;

  listContainer.innerHTML = '';

  if (repetitions.length === 0) {
    const emptyMsg = lang === 'el'
      ? 'Δεν βρέθηκαν κινήσεις για αυτή την επανάληψη.'
      : 'No transactions found for this repetition.';
    listContainer.innerHTML = `
      <div style="text-align: center; padding: 24px 16px; color: var(--text-secondary); font-size: 13.5px; line-height: 1.5;">
        ${emptyMsg}
      </div>
    `;
  } else {
    repetitions.forEach(tx => {
      // Format date
      let formattedDate = tx.date || '';
      try {
        const d = new Date(tx.date);
        if (!isNaN(d.getTime())) {
          formattedDate = d.toLocaleDateString(lang === 'el' ? 'el-GR' : 'en-US', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
          });
        }
      } catch (e) { }

      const amount = parseFloat(tx.amount || 0).toFixed(2);
      const catBadge = (typeof renderCategoryIconHtml === 'function')
        ? renderCategoryIconHtml(tx.category, { size: 'sm', transType: tx.type })
        : `<div style="font-size: 15px; flex-shrink: 0;">${tx.type === 'expense' ? '🔴' : '🟢'}</div>`;

      const rowHtml = `
        <div style="display: flex; flex-direction: row; align-items: center; justify-content: space-between; padding: 10px 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-card); gap: 10px; box-sizing: border-box; width: 100%; cursor: pointer;" onclick="openEditTransactionModalFromDetails('${tx.id}')">
          <div style="display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1;">
            ${catBadge}
            <div style="display: flex; flex-direction: column; min-width: 0; text-align: left; flex: 1;">
              <span style="font-weight: 600; color: var(--text-primary); font-size: 13.5px; word-break: break-word; line-height: 1.3;">${formattedDate}</span>
              <span style="font-size: 11.5px; color: var(--text-secondary); margin-top: 2px; word-break: break-word; line-height: 1.2;">${tx.category || ''}</span>
            </div>
          </div>
          <div style="display: flex; align-items: center; gap: 10px; flex-shrink: 0;">
            <span style="font-weight: 700; color: var(--text-primary); font-size: 13.5px; white-space: nowrap;">${amount}€</span>
            <button type="button" onclick="event.stopPropagation(); handleDeleteFromRecurringDetails('${tx.id}', '${template.id}', '${String(tx.date || '').split('T')[0]}')" style="background: rgba(239, 83, 80, 0.1); border: 1px solid rgba(239, 83, 80, 0.2); color: var(--danger); font-size: 13px; cursor: pointer; padding: 6px 10px; border-radius: 8px; transition: background-color 0.2s;" title="${lang === 'el' ? 'Διαγραφή' : 'Delete'}">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        </div>
      `;
      listContainer.insertAdjacentHTML('beforeend', rowHtml);
    });
  }

  openModal('recurring-details-modal');
}

function openEditTransactionModalFromDetails(txId) {
  const tx = (state.transactions || []).find(t => String(t.id) === String(txId));
  if (tx) {
    closeModal('recurring-details-modal');
    setTimeout(() => {
      openEditTransactionModal(tx, { instant: true });
    }, 320);
  }
}
window.openEditTransactionModalFromDetails = openEditTransactionModalFromDetails;

function handleDeleteFromRecurringDetails(txId, templateId, dateStr) {
  const tx = (state.transactions || []).find(t => String(t.id) === String(txId));
  const target = tx || { id: txId, recurring_template_id: templateId, date: dateStr };
  closeModal('recurring-details-modal');
  setTimeout(() => {
    openRecurringDeleteModal(target, dateStr, { instant: true });
  }, 320);
}
window.handleDeleteFromRecurringDetails = handleDeleteFromRecurringDetails;

function closeRecurringDetailsModal() {
  closeModal('recurring-details-modal');
  activeRecurringDetailsTemplateId = null;
}

async function saveRecurringTemplateName() {
  if (!activeRecurringDetailsTemplateId) return;
  const lang = state.lang || 'el';

  const nameInput = document.getElementById('recurring-details-name-input');
  const newName = nameInput ? nameInput.value.trim() : '';

  const template = (state.recurringTemplates || []).find(t => String(t.id) === String(activeRecurringDetailsTemplateId));
  if (!template) return;

  if (!newName) {
    showSyncToast(lang === 'el' ? '⚠️ Το όνομα δεν μπορεί να είναι κενό.' : '⚠️ The name cannot be empty.', 2500);
    return;
  }

  template.note = newName;

  // Save to localStorage
  localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));

  // Save to Supabase (Cloud Sync)
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    try {
      await state.supabaseClient
        .from('recurring_templates')
        .upsert([mapTemplateToDb(template)]);
    } catch (err) {
      console.warn('Failed to sync recurring template name to cloud:', err);
    }
  }

  showSyncToast(lang === 'el' ? '✅ Το όνομα αποθηκεύτηκε.' : '✅ Name saved.', 2500);

  // Refresh the templates list modal behind
  openRecurringTemplatesModal();
  // Re-open details modal to reflect the new name
  openRecurringDetailsModal(template.id);
}

// ============================================================
// RECURRING EDITOR: full management of a recurring template
// (start date, end date, day of month, preset) via calendar
// ============================================================
let activeRecurringEditTemplateId = null;
let _recurringEditMonths = [];

function openRecurringEditModal(templateId) {
  const template = (state.recurringTemplates || []).find(t => String(t.id) === String(templateId));
  if (!template) return;
  activeRecurringEditTemplateId = template.id;

  const lang = state.lang || 'el';

  // Title
  const titleEl = document.getElementById('recurring-edit-title');
  if (titleEl) titleEl.textContent = lang === 'el' ? '✏️ Επεξεργασία Επανάληψης' : '✏️ Edit Recurring';

  // Name
  const nameInput = document.getElementById('recurring-edit-name-input');
  if (nameInput) nameInput.value = template.note || '';

  // Start date
  const startDateStr = template.startDate || `${template.startYear || new Date().getFullYear()}-${String(template.startMonth || 1).padStart(2, '0')}-01`;
  const startInput = document.getElementById('recurring-edit-start');
  const startLabel = document.getElementById('recurring-edit-start-label');
  if (startInput) startInput.value = startDateStr;
  if (startLabel) {
    const parts = startDateStr.split('-');
    if (parts.length === 3) startLabel.textContent = `${parts[2]}/${parts[1]}/${parts[0]}`;
    else startLabel.textContent = startDateStr;
  }

  // Preset
  const presetSelect = document.getElementById('recurring-edit-preset');
  if (presetSelect) presetSelect.value = template.preset || 'monthly';

  // Months grid
  _recurringEditMonths = Array.isArray(template.months) ? template.months.slice() : [];
  renderRecurringEditMonthsGrid();

  // End type / end date
  const endType = template.endType || 'perpetual';
  const endDate = template.endDate || null;
  const btnPerpetual = document.getElementById('recurring-edit-end-perpetual');
  const btnDate = document.getElementById('recurring-edit-end-date');
  const endContainer = document.getElementById('recurring-edit-end-date-container');
  const endInput = document.getElementById('recurring-edit-end');
  const endLabel = document.getElementById('recurring-edit-end-label');

  if (endType === 'perpetual' || !endDate) {
    if (btnPerpetual) btnPerpetual.classList.add('active');
    if (btnDate) btnDate.classList.remove('active');
    if (endContainer) endContainer.style.display = 'none';
    if (endInput) endInput.value = '';
    if (endLabel) endLabel.textContent = lang === 'el' ? 'Επιλογή ημερομηνίας...' : 'Select date...';
  } else {
    if (btnPerpetual) btnPerpetual.classList.remove('active');
    if (btnDate) btnDate.classList.add('active');
    if (endContainer) endContainer.style.display = 'flex';
    if (endInput) endInput.value = endDate;
    if (endLabel) {
      const parts = endDate.split('-');
      if (parts.length === 3) endLabel.textContent = `${parts[2]}/${parts[1]}/${parts[0]}`;
      else endLabel.textContent = endDate;
    }
  }

  // Update summary when start/end dates change via the calendar
  const startInputEl = document.getElementById('recurring-edit-start');
  const endInputEl = document.getElementById('recurring-edit-end');
  if (startInputEl) startInputEl.oninput = () => updateRecurringEditSummary();
  if (endInputEl) endInputEl.oninput = () => updateRecurringEditSummary();

  updateRecurringEditSummary();
  openModal('recurring-edit-modal');
}

function closeRecurringEditModal() {
  closeModal('recurring-edit-modal');
  activeRecurringEditTemplateId = null;
}

function renderRecurringEditMonthsGrid() {
  const grid = document.getElementById('recurring-edit-months-grid');
  if (!grid) return;
  grid.innerHTML = '';
  const lang = state.lang || 'el';
  const monthNames = lang === 'en' ? ENGLISH_MONTHS_SHORT : GREEK_MONTHS_SHORT;
  for (let m = 1; m <= 12; m++) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'google-picker-btn';
    btn.textContent = monthNames[m - 1];
    if (_recurringEditMonths.includes(m)) btn.classList.add('active');
    btn.onclick = () => {
      const idx = _recurringEditMonths.indexOf(m);
      if (idx > -1) {
        if (_recurringEditMonths.length > 1) {
          _recurringEditMonths.splice(idx, 1);
          btn.classList.remove('active');
        }
      } else {
        _recurringEditMonths.push(m);
        btn.classList.add('active');
      }
      updateRecurringEditSummary();
    };
    grid.appendChild(btn);
  }
}

function onRecurringEditPresetChange() {
  const select = document.getElementById('recurring-edit-preset');
  if (!select) return;
  const val = select.value;
  const monthsContainer = document.getElementById('recurring-edit-months-container');
  if (monthsContainer) {
    if (val === 'specific_months') {
      monthsContainer.style.display = 'flex';
      if (_recurringEditMonths.length === 0) {
        const startVal = document.getElementById('recurring-edit-start').value;
        const currentMonth = startVal ? new Date(startVal).getMonth() + 1 : new Date().getMonth() + 1;
        _recurringEditMonths = [currentMonth];
        renderRecurringEditMonthsGrid();
      }
    } else {
      monthsContainer.style.display = 'none';
    }
  }
  updateRecurringEditSummary();
}

function selectRecurringEditEndType(type) {
  const btnPerpetual = document.getElementById('recurring-edit-end-perpetual');
  const btnDate = document.getElementById('recurring-edit-end-date');
  const endContainer = document.getElementById('recurring-edit-end-date-container');
  const lang = state.lang || 'el';

  if (type === 'perpetual') {
    if (btnPerpetual) btnPerpetual.classList.add('active');
    if (btnDate) btnDate.classList.remove('active');
    if (endContainer) endContainer.style.display = 'none';
    const endInput = document.getElementById('recurring-edit-end');
    if (endInput) endInput.value = '';
  } else {
    if (btnPerpetual) btnPerpetual.classList.remove('active');
    if (btnDate) btnDate.classList.add('active');
    if (endContainer) endContainer.style.display = 'flex';
    const endInput = document.getElementById('recurring-edit-end');
    if (endInput && !endInput.value) {
      const today = new Date();
      const endOfYear = new Date(today.getFullYear(), 11, 31);
      const yyyy = endOfYear.getFullYear();
      const mm = String(endOfYear.getMonth() + 1).padStart(2, '0');
      const dd = String(endOfYear.getDate()).padStart(2, '0');
      endInput.value = `${yyyy}-${mm}-${dd}`;
      const endLabel = document.getElementById('recurring-edit-end-label');
      if (endLabel) endLabel.textContent = `${dd}/${mm}/${yyyy}`;
    }
  }
  updateRecurringEditSummary();
}

function updateRecurringEditSummary() {
  const summaryText = document.getElementById('recurring-edit-summary-text');
  if (!summaryText) return;
  const lang = state.lang || 'el';
  const preset = document.getElementById('recurring-edit-preset') ? document.getElementById('recurring-edit-preset').value : 'monthly';
  const endInput = document.getElementById('recurring-edit-end');
  const endDate = endInput ? endInput.value : '';

  let freqPart = '';
  if (preset === 'daily') freqPart = lang === 'el' ? 'Κάθε μέρα' : 'Daily';
  else if (preset === 'weekly') freqPart = lang === 'el' ? 'Κάθε εβδομάδα' : 'Weekly';
  else if (preset === 'monthly') freqPart = lang === 'el' ? 'Κάθε μήνα' : 'Monthly';
  else if (preset === 'yearly') freqPart = lang === 'el' ? 'Κάθε χρόνο' : 'Yearly';
  else if (preset === 'specific_months') {
    const monthNames = lang === 'en' ? ENGLISH_MONTHS_SHORT : GREEK_MONTHS_SHORT;
    const selectedNames = _recurringEditMonths.map(m => monthNames[m - 1]).join(', ');
    freqPart = selectedNames ? (lang === 'el' ? `Σε μήνες (${selectedNames})` : `In months (${selectedNames})`) : (lang === 'el' ? 'Επιλεγμένοι μήνες' : 'Selected months');
  } else {
    freqPart = 'Custom';
  }

  let endPart = '';
  if (endDate) {
    const parts = endDate.split('-');
    if (parts.length === 3) endPart = lang === 'el' ? `μέχρι τις ${parts[2]}/${parts[1]}/${parts[0]}` : `until ${parts[2]}/${parts[1]}/${parts[0]}`;
    else endPart = lang === 'el' ? `μέχρι ${endDate}` : `until ${endDate}`;
  } else {
    endPart = lang === 'el' ? 'για πάντα' : 'forever';
  }

  summaryText.textContent = lang === 'el'
    ? `Θα δημιουργούνται: ${freqPart} ${endPart}`
    : `Will be created: ${freqPart} ${endPart}`;
}

async function saveRecurringTemplateEdit() {
  if (!activeRecurringEditTemplateId) return;
  const lang = state.lang || 'el';
  const template = (state.recurringTemplates || []).find(t => String(t.id) === String(activeRecurringEditTemplateId));
  if (!template) return;

  const nameInput = document.getElementById('recurring-edit-name-input');
  const newName = nameInput ? nameInput.value.trim() : '';
  if (!newName) {
    showSyncToast(lang === 'el' ? '⚠️ Το όνομα δεν μπορεί να είναι κενό.' : '⚠️ The name cannot be empty.', 2500);
    return;
  }

  const startInput = document.getElementById('recurring-edit-start');
  const startDateStr = startInput ? startInput.value : '';
  if (!startDateStr) {
    showSyncToast(lang === 'el' ? '⚠️ Επιλέξτε ημερομηνία έναρξης.' : '⚠️ Please select a start date.', 2500);
    return;
  }

  const preset = document.getElementById('recurring-edit-preset') ? document.getElementById('recurring-edit-preset').value : 'monthly';
  const endInput = document.getElementById('recurring-edit-end');
  const endDate = endInput ? endInput.value : '';

  // Validate specific_months
  if (preset === 'specific_months' && _recurringEditMonths.length === 0) {
    showSyncToast(lang === 'el' ? '⚠️ Επιλέξτε τουλάχιστον έναν μήνα.' : '⚠️ Please select at least one month.', 2500);
    return;
  }

  // Validate end date >= start date
  if (endDate && endDate < startDateStr) {
    showSyncToast(lang === 'el' ? '⚠️ Η ημερομηνία λήξης πρέπει να είναι μετά την έναρξη.' : '⚠️ End date must be after start date.', 2500);
    return;
  }

  // 1. Remove all existing transactions linked to this template (local + cloud)
  const templateIdStr = String(template.id);
  const linkedTxs = (state.transactions || []).filter(tx => String(tx.recurring_template_id || '') === templateIdStr);
  const linkedIds = linkedTxs.map(tx => tx.id);
  if (linkedIds.length > 0) {
    state.transactions = state.transactions.filter(tx => !linkedIds.includes(tx.id));
    localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));
    if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
      try {
        await state.supabaseClient.from('transactions').delete().in('id', linkedIds);
      } catch (err) {
        console.warn('Failed to delete old recurring transactions from cloud:', err);
      }
    }
  }

  // 2. Update the template fields
  template.note = newName;
  template.preset = preset;
  template.months = preset === 'specific_months' ? _recurringEditMonths.slice() : [];
  template.days = [];
  template.startDate = startDateStr;
  template.startYear = new Date(startDateStr).getFullYear();
  template.startMonth = new Date(startDateStr).getMonth() + 1;
  if (endDate) {
    template.endType = 'date';
    template.endDate = endDate;
  } else {
    template.endType = 'perpetual';
    template.endDate = null;
  }

  // Clear any deleted-dates markers so regeneration is clean
  if (template.description) {
    template.description = (template.description || '').split('||deleted_dates:')[0].trim();
  }

  // 3. Save template locally + cloud
  localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    try {
      await state.supabaseClient.from('recurring_templates').upsert([mapTemplateToDb(template)]);
    } catch (err) {
      console.warn('Failed to sync recurring template edit to cloud:', err);
    }
  }

  // 4. Regenerate transactions for this template across all relevant months
  regenerateRecurringTemplateTransactions(template);

  showSyncToast(lang === 'el' ? '✅ Η επανάληψη ενημερώθηκε και αναδημιουργήθηκε.' : '✅ Recurring updated and regenerated.', 3000);

  closeRecurringEditModal();
  openRecurringTemplatesModal();
  openRecurringDetailsModal(template.id);
}

// Regenerate all recurring transactions for a single template across all months
// from its start date up to end date (or forever), skipping deleted dates.
function regenerateRecurringTemplateTransactions(template) {
  if (!template) return;
  const preset = template.preset || 'monthly';
  const startDate = new Date(template.startDate || new Date().toISOString().split('T')[0]);
  const startYear = startDate.getFullYear();
  const startMonth = startDate.getMonth(); // 0-indexed
  const startDay = startDate.getDate();

  const endDateStr = template.endDate || null;
  const endLimit = endDateStr ? new Date(endDateStr) : null;

  // Cap future generation to 12 months from today to avoid runaway creation
  const today = new Date();
  const maxFuture = new Date(today.getFullYear(), today.getMonth() + 12, 1);

  const deletedDates = getDeletedDatesFromTemplate(template);

  let created = 0;
  let year = startYear;
  let month = startMonth;

  while (true) {
    const yearMonth = new Date(year, month, 1);
    if (yearMonth > maxFuture) break;
    if (endLimit && yearMonth > endLimit) break;

    const monthNum = month + 1;
    const lastDay = new Date(year, month + 1, 0).getDate();
    const datesToCreate = [];

    if (preset === 'daily') {
      for (let d = 1; d <= lastDay; d++) {
        if (year === startYear && month === startMonth && d < startDay) continue;
        datesToCreate.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
      }
    } else if (preset === 'weekly') {
      const targetDayOfWeek = startDate.getDay();
      for (let d = 1; d <= lastDay; d++) {
        const dObj = new Date(year, month, d);
        if (dObj.getDay() === targetDayOfWeek) {
          if (year === startYear && month === startMonth && d < startDay) continue;
          datesToCreate.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
        }
      }
    } else if (preset === 'monthly') {
      const day = Math.min(startDay, lastDay);
      if (!(year === startYear && month === startMonth && day < startDay)) {
        datesToCreate.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
      }
    } else if (preset === 'yearly') {
      if (month === startMonth) {
        const day = Math.min(startDay, lastDay);
        datesToCreate.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
      }
    } else if (preset === 'specific_months') {
      if (template.months && template.months.includes(monthNum)) {
        const day = Math.min(startDay, lastDay);
        if (!(year === startYear && month === startMonth && day < startDay)) {
          datesToCreate.push(`${year}-${String(monthNum).padStart(2, '0')}-${String(day).padStart(2, '0')}`);
        }
      }
    }

    datesToCreate.forEach(dateString => {
      if (endLimit && dateString > endDateStr) return;
      if (deletedDates.includes(dateString)) return;

      const expectedDeterministicId = generateDeterministicUUID(template.id, dateString);
      const matchingExisting = state.transactions.find(t => {
        const tDate = String(t.date || '').split('T')[0].split(' ')[0];
        if (tDate !== dateString) return false;
        if (t.id === expectedDeterministicId) return true;
        if (t.recurring_template_id && String(t.recurring_template_id) === String(template.id)) return true;
        const tAmount = (parseFloat(t.amount) || 0).toFixed(2);
        const templAmount = (parseFloat(template.amount) || 0).toFixed(2);
        if (tAmount === templAmount && t.type === template.type) {
          const tNote = normalizeGreekString(t.note || t.description || '');
          const templNote = normalizeGreekString(template.note || template.description || '');
          const notesMatch = tNote.length > 0 && templNote.length > 0 && (tNote === templNote || tNote.includes(templNote) || templNote.includes(tNote));
          if (notesMatch) return true;
          if (isSameCategory(t.category, template.category) && (!tNote || !templNote || notesMatch)) return true;
        }
        return false;
      });
      if (matchingExisting) {
        if (!matchingExisting.recurring_template_id) {
          matchingExisting.recurring_template_id = template.id;
        }
        return;
      }

      const newTx = {
        id: expectedDeterministicId,
        recurring_template_id: template.id,
        date: dateString,
        type: template.type,
        amount: parseFloat(template.amount),
        currency: template.currency || 'EUR',
        category: template.category,
        subcategory: template.subcategory || '',
        account_from: template.account_from,
        account_to: template.type === 'transfer' ? template.account_to : null,
        note: template.note,
        description: template.description || '',
        user_id: template.user_id || (state.currentUser ? state.currentUser.id : null),
        is_shared: template.is_shared !== undefined ? template.is_shared : (state.partnerProfile !== null),
        family_id: template.family_id || (state.userProfile ? state.userProfile.family_id : null),
        created_at: new Date().toISOString()
      };
      computeCurrencyFields(newTx);
      // HIGH-EXPENSE ALERT: recurring-generated expenses also respect the
      // "Single Expense Alert" limit (previously only manual saves fired it).
      checkHighExpenseAlert(newTx);
      saveTransactionOffline(newTx);
      if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
        const { description, is_shared, photo_local_uri, photo_url, receipt, fx_snapshot, ...dbPayload } = newTx;
        (async () => {
          try {
            const { error } = await promiseTimeout(
              state.supabaseClient.from('transactions').upsert([dbPayload]),
              12000
            );
            if (error) throw error;
          } catch (err) {
            // If the server-side cloud limit trigger rejected this insert (free
            // user over the monthly limit), keep the transaction locally and
            // queue it for later sync — never drop financial data.
            console.warn('Cloud save failed for regenerated recurring, queueing:', newTx.id, err);
            enqueueSyncMutation('save', newTx);
          }
        })();
      }
      created++;
    });

    // Advance to next month
    month++;
    if (month > 11) {
      month = 0;
      year++;
    }
    if (year > maxFuture.getFullYear() + 1) break;
  }

  cleanCrossLanguageRecurringDuplicates();
  calculateInitialBalances();
  updateUI();
  return created;
}

async function deleteRecurringTemplate(id) {
  if (!id) return;
  openRecurringDeleteModal(id);
}

// Trash Bin Management
function openTrashBinModal() {
  renderTrashBinList();
  openModal('trash-bin-modal');
}

// Fetch deleted transactions (status='deleted') from the cloud into the local
// trash bin. This replaces the legacy deleted_transactions + tombstone mechanism:
// the trash is now a simple query on the transactions table, so it stays
// consistent across all devices (web + APK).
async function fetchTrashFromCloud() {
  if (!state.isSupabaseEnabled || !state.supabaseClient || !state.currentUser) return;
  try {
    const userId = state.currentUser.id;
    const partnerId = state.partnerProfile ? state.partnerProfile.id : null;
    const familyId = state.userProfile ? state.userProfile.family_id : null;

    const trashQuery = state.supabaseClient
      .from('transactions')
      .select('*')
      .eq('status', 'deleted')
      .order('deleted_at', { ascending: false })
      .limit(100);

    const { data, error } = await promiseTimeout(trashQuery, 15000);
    if (error) {
      console.warn('Cloud trash fetch error:', error);
      return;
    }

    // Preserve locally-stored recurring trash groups (is_recurring_group: true).
    // These are NOT rows in the transactions table — they are local-only objects
    // holding the full series snapshot + template backup. The cloud query above
    // only returns individual soft-deleted transactions, so without merging them
    // back in, a recurring group deleted moments ago would vanish from the trash
    // the next time it is opened (until the user leaves and re-enters the tab).
    const recurringGroups = (state.trashTransactions || []).filter(t => t && t.is_recurring_group);

    // IMPORTANT: The Supabase DB may be EMPTY (all data is local on device). The
    // cloud query above returns only soft-deleted rows that exist in the cloud.
    // We must MERGE the cloud results with the locally-stored trash items instead
    // of replacing them — otherwise locally-deleted items (which never reached the
    // cloud) would vanish from the trash the moment it is opened.
    const cloudItems = data || [];
    const cloudIds = new Set(cloudItems.map(t => String(t.id)));
    const localItems = (state.trashTransactions || []).filter(t => t && !t.is_recurring_group && !cloudIds.has(String(t.id)));

    // Merge: recurring groups first (newest deletion on top), then cloud items,
    // then any remaining local-only items that are not already in the cloud.
    state.trashTransactions = [...recurringGroups, ...cloudItems, ...localItems];
    localStorage.setItem('deleted_transactions_trash', JSON.stringify(state.trashTransactions));

    // Refresh the trash count badge
    const trashCount = state.trashTransactions.length;
    const hubTrashCountEl = document.getElementById('hub-trash-count');
    if (hubTrashCountEl) hubTrashCountEl.textContent = trashCount;
  } catch (err) {
    console.warn('Failed to fetch cloud trash:', err);
  }
}

async function renderTrashBinList() {
  // Pull the latest deleted transactions from the cloud before rendering so the
  // trash stays consistent across devices.
  await fetchTrashFromCloud();

  const container = document.getElementById('trash-bin-list-container');
  if (!container) return;

  container.innerHTML = '';
  const trashItems = state.trashTransactions || [];
  const lang = state.lang || 'el';

  const btnEmpty = document.getElementById('btn-empty-trash');
  if (btnEmpty) {
    btnEmpty.style.display = trashItems.length === 0 ? 'none' : 'flex';
  }

  if (trashItems.length === 0) {
    const emptyMsg = TRANSLATIONS[lang]['no_trash_items'] || 'The trash bin is empty.';
    container.innerHTML = `
      <div style="text-align: center; padding: 32px 16px; color: var(--text-secondary); font-size: 14px; line-height: 1.5;">
        ${emptyMsg}
      </div>
    `;
    return;
  }

  // Sort trash items by deleted_at descending (newest deletion first)
  const sortedTrash = [...trashItems].sort((a, b) => {
    return new Date(b.deleted_at || 0) - new Date(a.deleted_at || 0);
  });

  sortedTrash.forEach(t => {
    if (t.is_recurring_group) {
      // Resolve the theme accent at runtime so the recurring-group badge follows
      // the active theme. renderCategoryIconHtml()/hexToRgba() need a concrete
      // hex value, so var(--accent) alone cannot be passed straight through.
      const color = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#7c6af7';
      const restoreText = TRANSLATIONS[lang]['restore'] || 'Restore';
      const badgeHtml = (typeof renderCategoryIconHtml === 'function')
        ? renderCategoryIconHtml(t.category || '🔄', { size: 'sm', customColor: color })
        : `<div style="width: 40px; height: 40px; border-radius: 50%; background: ${color}20; color: ${color}; display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0;"><i class="fa-solid fa-arrows-rotate"></i></div>`;

      const itemHtml = `
        <div class="trash-item-row" style="display: flex; flex-direction: row; align-items: center; justify-content: space-between; padding: 12px 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-card); gap: 12px; box-sizing: border-box; width: 100%;">
          <div style="display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1; flex-direction: row;">
            ${badgeHtml}
            <div style="display: flex; flex-direction: column; min-width: 0; text-align: left; flex: 1;">
              <span style="font-weight: 700; color: var(--text-primary); font-size: 14px; word-break: break-word; line-height: 1.3;">${t.note || (TRANSLATIONS[lang] && TRANSLATIONS[lang]['recurring_label']) || 'Επαναλαμβανόμενη'}</span>
              <span style="font-size: 11.5px; color: var(--text-secondary); margin-top: 3px; word-break: break-word; line-height: 1.2;">
                ${t.subtitle || '🔄 ' + ((TRANSLATIONS[lang] && TRANSLATIONS[lang]['recurring_label']) || 'Επαναλαμβανόμενη')} • ${getCurrencySymbol()} ${formatDisplayAmount(t.amount, t.currency || state.mainCurrency || 'EUR')}
              </span>
            </div>
          </div>
          <div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0;">
            <button class="restore-btn" onclick="restoreTrashGroup('${t.id}')" style="background: var(--primary); border: none; color: #ffffff; font-size: 12px; font-weight: 600; cursor: pointer; padding: 6px 12px; border-radius: 8px; transition: opacity 0.2s; outline: none;">
              ${restoreText}
            </button>
            <button onclick="deleteSingleTrashItem('${t.id}')" style="background: transparent; border: none; color: var(--danger); font-size: 13px; cursor: pointer; padding: 6px; border-radius: 6px;" title="${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['permanent_delete']) || 'Οριστική Διαγραφή'}">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        </div>
      `;
      container.insertAdjacentHTML('beforeend', itemHtml);
      return;
    }
    // Find category styling
    const catVisual = (typeof getCategoryVisual === 'function')
      ? getCategoryVisual(t.category, t.type)
      : { iconClass: 'fa-solid fa-shapes', color: '#78909c' };
    const color = catVisual.color || '#78909c';
    const badgeHtml = (typeof renderCategoryIconHtml === 'function')
      ? renderCategoryIconHtml(t.category, { size: 'sm', transType: t.type })
      : `<div style="width: 40px; height: 40px; border-radius: 50%; background: ${color}20; color: ${color}; display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0;">${(catVisual.iconClass && typeof renderIconGlyph === 'function') ? renderIconGlyph(catVisual.iconClass) : (catVisual.iconClass ? `<i class="${catVisual.iconClass}"></i>` : '🧩')}</div>`;

    const restoreText = TRANSLATIONS[lang]['restore'] || 'Restore';

    // Format date nicely
    let formattedDate = t.date || '';
    try {
      const d = new Date(t.date);
      if (!isNaN(d.getTime())) {
        formattedDate = d.toLocaleDateString(lang === 'el' ? 'el-GR' : 'en-US', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric'
        });
      }
    } catch (e) { }

    const itemHtml = `
      <div class="trash-item-row" style="display: flex; flex-direction: row; align-items: center; justify-content: space-between; padding: 12px 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-card); gap: 12px; box-sizing: border-box; width: 100%;">
        <div style="display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1; flex-direction: row;">
          ${badgeHtml}
          <div style="display: flex; flex-direction: column; min-width: 0; text-align: left; flex: 1;">
            <span style="font-weight: 700; color: var(--text-primary); font-size: 14px; word-break: break-word; line-height: 1.3;">${t.note || ''}</span>
            <span style="font-size: 11.5px; color: var(--text-secondary); margin-top: 3px; word-break: break-word; line-height: 1.2;">
              ${formattedDate} • ${getCurrencySymbol()} ${formatDisplayAmount(t.amount, t.currency || state.mainCurrency || 'EUR')}
            </span>
          </div>
        </div>
        <div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0;">
          <button class="restore-btn" onclick="restoreTransaction('${t.id}')" style="background: var(--primary); border: none; color: #ffffff; font-size: 12px; font-weight: 600; cursor: pointer; padding: 6px 12px; border-radius: 8px; transition: opacity 0.2s; outline: none;">
            ${restoreText}
          </button>
          <button onclick="deleteSingleTrashItem('${t.id}')" style="background: transparent; border: none; color: var(--danger); font-size: 13px; cursor: pointer; padding: 6px; border-radius: 6px;" title="${(TRANSLATIONS[lang] && TRANSLATIONS[lang]['permanent_delete']) || 'Οριστική Διαγραφή'}">
            <i class="fa-solid fa-trash-can"></i>
          </button>
        </div>
      </div>
    `;
    container.insertAdjacentHTML('beforeend', itemHtml);
  });
}

async function restoreTransaction(id) {
  if (!id) return;

  const itemToRestore = (state.trashTransactions || []).find(t => String(t.id) === String(id));
  if (!itemToRestore) return;

  // 1. Remove from trash and permanent deleted tombstones
  state.trashTransactions = (state.trashTransactions || []).filter(t => String(t.id) !== String(id));
  localStorage.setItem('deleted_transactions_trash', JSON.stringify(state.trashTransactions));
  try {
    const perm = JSON.parse(localStorage.getItem('permanent_deleted_tx_ids') || '[]') || [];
    const filtered = perm.filter(pId => String(pId) !== String(id));
    if (filtered.length !== perm.length) {
      localStorage.setItem('permanent_deleted_tx_ids', JSON.stringify(filtered));
    }
  } catch (_) { }

  // Remove deletion markers and explicitly set status='active' before saving
  // back to transactions. Without status='active', the transaction stays
  // status='deleted' and collectPermanentlyDeletedTxIds() immediately excludes it.
  const cleanedItem = { ...itemToRestore };
  delete cleanedItem.deleted_at;
  delete cleanedItem.deleted_by;
  cleanedItem.status = 'active';

  // 2. Add back to transactions (replace if already present, otherwise append)
  const existingIdx = state.transactions.findIndex(t => String(t.id) === String(cleanedItem.id));
  if (existingIdx !== -1) {
    state.transactions[existingIdx] = cleanedItem;
  } else {
    state.transactions.push(cleanedItem);
  }
  localStorage.setItem('offline_transactions', JSON.stringify(state.transactions));

  if (typeof _markRecentlySaved === 'function') {
    _markRecentlySaved(cleanedItem.id);
  }

  // If this transaction was linked to a recurring template, un-blacklist its date
  // so future recurring processing or regeneration doesn't treat it as deleted.
  if (cleanedItem.recurring_template_id && cleanedItem.date) {
    const txDate = String(cleanedItem.date).split('T')[0].split(' ')[0];
    const key = `${cleanedItem.recurring_template_id}_${txDate}`;
    if (state.deletedRecurringDates && state.deletedRecurringDates.includes(key)) {
      state.deletedRecurringDates = state.deletedRecurringDates.filter(k => k !== key);
      localStorage.setItem('deleted_recurring_dates', JSON.stringify(state.deletedRecurringDates));
    }
    const template = (state.recurringTemplates || []).find(t => String(t.id) === String(cleanedItem.recurring_template_id));
    if (template && template.description && template.description.includes('||deleted_dates:')) {
      const parts = template.description.split('||deleted_dates:');
      const dates = (parts[1] || '').split(',').map(s => s.trim()).filter(Boolean);
      const filteredDates = dates.filter(d => d !== txDate);
      template.description = filteredDates.length > 0 ? `${parts[0].trim()} ||deleted_dates:${filteredDates.join(',')}` : parts[0].trim();
      localStorage.setItem('recurring_templates', JSON.stringify(state.recurringTemplates));
    }
  }

  // 3. Save to Supabase (Cloud Sync) — status model: set status back to 'active'
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    enqueueSyncMutation('upsert', cleanedItem.id);
    try {
      // DUAL-WRITE (Phase 2): remove the legacy deleted_transactions backup row.
      await state.supabaseClient
        .from('deleted_transactions')
        .delete()
        .eq('id', id);

      // Restore by flipping status back to 'active' (no need to re-insert).
      await state.supabaseClient
        .from('transactions')
        .update({ status: 'active', deleted_at: null, deleted_by: null })
        .eq('id', id);
      dequeueSyncMutation('upsert', cleanedItem.id);
    } catch (err) {
      console.warn('Cloud restore failed, keeping in queue:', err);
    }
  }

  // 4. Update UI & re-render
  calculateInitialBalances();
  updateUI();
  renderTrashBinList();
}

async function emptyTrashBin() {
  const lang = state.lang || 'el';
  const confirmMsg = lang === 'el' ? 'Να διαγραφούν οριστικά αυτές οι κινήσεις;' : 'Permanently delete these transactions?';

  const confirmed = await showConfirm(confirmMsg, lang === 'el' ? 'Εκκαθάριση Κάδου' : 'Empty Trash', '🗑️');
  if (!confirmed) return;

  const itemsBeingEmptied = (state.trashTransactions || []).slice();

  // Clear on Supabase if logged in — hard-delete all status='deleted' rows across
  // the SAME scope the trash reads from (user + family + partner).
  if (state.isSupabaseEnabled && state.supabaseClient && state.currentUser) {
    const userId = state.currentUser.id;
    const partnerId = state.partnerProfile ? state.partnerProfile.id : null;
    const familyId = state.userProfile ? state.userProfile.family_id : null;

    let delQuery = state.supabaseClient
      .from('transactions')
      .delete()
      .eq('status', 'deleted');

    if (familyId && partnerId) {
      delQuery = delQuery.or(`family_id.eq.${familyId},user_id.eq.${userId},user_id.eq.${partnerId}`);
    } else if (familyId) {
      delQuery = delQuery.or(`family_id.eq.${familyId},user_id.eq.${userId}`);
    } else if (partnerId) {
      delQuery = delQuery.or(`user_id.eq.${userId},user_id.eq.${partnerId}`);
    } else {
      delQuery = delQuery.eq('user_id', userId);
    }

    try {
      const { error } = await delQuery;
      if (error) console.warn('Failed to clear deleted transactions on Supabase:', error);
    } catch (err) {
      console.warn('Failed to clear deleted transactions on Supabase:', err);
    }
  }

  // Durable tombstone: purge every emptied ID from all local caches (offline_transactions,
  // sync queue, state) and record a cloud tombstone so no sync path can ever resurrect
  // them (autoSyncMissingTransactionsToCloud, cachedMissingFromCloud, processSyncQueue,
  // realtime, restore).
  try {
    const allEmptiedIds = [];
    itemsBeingEmptied.forEach(t => {
      if (Array.isArray(t.affectedTransactionIds) && t.affectedTransactionIds.length > 0) {
        t.affectedTransactionIds.forEach(tid => allEmptiedIds.push(tid));
      } else if (t.id) {
        allEmptiedIds.push(t.id);
      }
    });
    if (allEmptiedIds.length > 0) {
      purgePermanentlyDeletedTxIds(allEmptiedIds, { writeCloudTombstone: true });
    }
  } catch (err) {
    console.warn('Failed to purge permanently deleted transaction IDs:', err);
  }

  // Save notes of items in trash to dismissed_recovered_templates before emptying
  try {
    let dismissed = JSON.parse(localStorage.getItem('dismissed_recovered_templates') || '[]');
    itemsBeingEmptied.forEach(t => {
      if (t.note && !dismissed.includes(t.note)) {
        dismissed.push(t.note);
      }
    });
    localStorage.setItem('dismissed_recovered_templates', JSON.stringify(dismissed));
  } catch (e) { }

  state.trashTransactions = [];
  localStorage.setItem('deleted_transactions_trash', JSON.stringify(state.trashTransactions));

  updateUI();
  renderTrashBinList();
}

